sp_widget.client_script:
api.controller = function($scope, $timeout, $sce) {

    var c = this;

    var MAX_RESUME_BYTES = 3 * 1024 * 1024;   // 3 MB (same as server)
    var ALLOWED_EXT = ['pdf', 'doc', 'docx'];

    var SKILL_KEYS  = ['skills', 'skillList', 'skillCatalog', 'completion', 'profileCompletion'];
    var RESUME_KEYS = ['resume', 'resumeUrl', 'resumeAttachmentId', 'completion', 'profileCompletion'];

    var alertTimer = null;
    var resumeInputEl = null;
    var cachedResume = null;     // { key, fileName, blobUrl, safeUrl, isPdf }


    /* =========================================================
       STATE
       ========================================================= */

    c.isEditing = false;
    c.isSaving = false;
    c.isUploadingResume = false;
    c.isLoadingResume = false;

    c.showSuccess = false;
    c.showError = false;
    c.successMessage = '';
    c.errorMessage = '';
    c.formError = '';

    c.originalProfile = null;

    // resume preview
    c.showResumePreview = false;
    c.resumePreview = null;

    // add skill
    c.showAddSkillModal = false;
    c.selectedSkillIds = [];
    c.skillCatalogSearch = '';
    c.addSkillError = '';
    c.addSkillSuccess = '';
    c.isAddingSkills = false;

    // remove skill
    c.isRemovingSkill = false;

    // request skill
    c.showSkillRequestModal = false;
    c.skillRequest = { requestedTerm: '', reason: '' };
    c.skillRequestError = '';
    c.skillRequestSuccess = '';
    c.isSubmittingSkillRequest = false;


    /* =========================================================
       HELPERS
       ========================================================= */

    function isStudent() {
        return !!(c.data && c.data.profile && c.data.profile.isStudent === true);
    }

    function notify(type, message) {

        c.showSuccess = (type === 'success');
        c.showError = (type === 'error');

        if (type === 'success') {
            c.successMessage = message;
        } else {
            c.errorMessage = message;
        }

        if (alertTimer) {
            $timeout.cancel(alertTimer);
        }

        alertTimer = $timeout(function() {
            c.showSuccess = false;
            c.showError = false;
        }, type === 'error' ? 8000 : 5000);
    }

    /*
     * Single place that talks to the Server Script.
     * Resolves with the widget data object returned by the server.
     */
    function callServer(action, payload) {

        c.data.action = action;

        angular.forEach(payload || {}, function(value, key) {
            c.data[key] = value;
        });

        return c.server.update().then(function(response) {
            return (response && response.data) ? response.data : (response || {});
        });
    }

    function cleanRequest(keys) {

        for (var i = 0; i < keys.length; i++) {
            delete c.data[keys[i]];
        }

        c.data.action = 'load';
    }

    /*
     * Copies only the given keys from the server profile into the profile
     * the user is editing, so unsaved edits are NOT lost.
     */
    function mergeProfile(freshProfile, keys, snapshot) {

        var live = snapshot || c.data.profile || {};
        var fresh = freshProfile || {};

        for (var i = 0; i < keys.length; i++) {

            live[keys[i]] = angular.copy(fresh[keys[i]]);

            if (c.originalProfile) {
                c.originalProfile[keys[i]] = angular.copy(fresh[keys[i]]);
            }
        }

        c.data.profile = live;
    }

    function restoreProfile(snapshot) {
        if (snapshot) {
            c.data.profile = snapshot;
        }
    }

    function getExt(fileName) {
        var name = String(fileName || '');
        return name.indexOf('.') !== -1 ? name.split('.').pop().toLowerCase() : '';
    }

    c.isPdfName = function(fileName) {
        return getExt(fileName) === 'pdf';
    };


    /* =========================================================
       EDIT MODE
       ========================================================= */

    c.startEditing = function() {

        if (!isStudent()) {
            notify('error', 'Only students can edit their profile.');
            return;
        }

        c.originalProfile = angular.copy(c.data.profile);
        c.isEditing = true;
        c.formError = '';
        c.showSuccess = false;
        c.showError = false;
    };

    c.cancelEditing = function() {

        if (c.originalProfile) {
            c.data.profile = angular.copy(c.originalProfile);
        }

        c.isEditing = false;
        c.isSaving = false;
        c.formError = '';
        c.showSuccess = false;
        c.showError = false;
    };


    /* =========================================================
       CHANGE DETECTION  (academic fields are not editable)
       ========================================================= */

    var EDITABLE_FIELDS = [
        'fullName', 'email', 'mobile', 'gender', 'fatherName', 'fatherMobile',
        'address', 'language', 'alternateEmail', 'git', 'linkedin'
    ];

    c.hasChanges = function() {

        if (!c.originalProfile || !c.data || !c.data.profile) {
            return false;
        }

        for (var i = 0; i < EDITABLE_FIELDS.length; i++) {

            var f = EDITABLE_FIELDS[i];
            var oldValue = c.originalProfile[f];
            var newValue = c.data.profile[f];

            if (oldValue === null || oldValue === undefined) { oldValue = ''; }
            if (newValue === null || newValue === undefined) { newValue = ''; }

            if (String(oldValue).trim() !== String(newValue).trim()) {
                return true;
            }
        }

        return false;
    };


    /* =========================================================
       VALIDATION  (returns an error message, or '' when valid)
       ========================================================= */

    var EMAIL_REGEX = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

    function digits(value) {
        return String(value || '').replace(/[^0-9]/g, '');
    }

    c.validateProfile = function() {

        var p = c.data && c.data.profile;

        if (!p) { return 'Profile information is not available.'; }

        if (!p.fullName || String(p.fullName).trim().length < 2) {
            return 'Please enter a valid student name.';
        }

        if (!p.email || !EMAIL_REGEX.test(String(p.email).trim())) {
            return 'Please enter a valid email address.';
        }

        var mobileDigits = digits(p.mobile);
        if (mobileDigits.length < 10 || mobileDigits.length > 15) {
            return 'Please enter a valid mobile number (10 to 15 digits).';
        }

        if (p.fatherMobile) {
            var fm = digits(p.fatherMobile);
            if (fm.length < 10 || fm.length > 15) {
                return 'Please enter a valid parent / guardian mobile number.';
            }
        }

        if (p.alternateEmail && !EMAIL_REGEX.test(String(p.alternateEmail).trim())) {
            return 'Please enter a valid alternate email address.';
        }

        if (p.git && String(p.git).toLowerCase().indexOf('github.com') === -1) {
            return 'Please enter a valid GitHub URL.';
        }

        if (p.linkedin && String(p.linkedin).toLowerCase().indexOf('linkedin.com') === -1) {
            return 'Please enter a valid LinkedIn URL.';
        }

        return '';
    };


    /* =========================================================
       SAVE PROFILE
       ========================================================= */

    c.updateProfile = function() {

        if (c.isSaving) { return; }

        if (!isStudent()) {
            notify('error', 'Only students can update their profile.');
            return;
        }

        c.formError = '';

        if (!c.hasChanges()) {
            c.formError = 'No changes were made to your profile.';
            notify('error', c.formError);
            return;
        }

        var validationError = c.validateProfile();

        if (validationError) {
            c.formError = validationError;
            notify('error', validationError);
            return;
        }

        var p = c.data.profile;
        var snapshot = angular.copy(p);

        c.isSaving = true;

        callServer('update_profile', {

            profileUpdate: {
                fullName:       p.fullName || '',
                email:          p.email || '',
                mobile:         p.mobile || '',
                gender:         p.gender || '',
                fatherName:     p.fatherName || '',
                fatherMobile:   p.fatherMobile || '',
                address:        p.address || '',
                language:       p.language || '',
                alternateEmail: p.alternateEmail || '',
                git:            p.git || '',
                linkedin:       p.linkedin || ''
            }

        }).then(

            function(result) {

                var success = (result.success === true);
                var freshProfile = result.profile;
                var message = result.message;
                var error = result.error;

                c.isSaving = false;
                cleanRequest(['profileUpdate']);

                if (success && freshProfile) {

                    c.data.profile = angular.copy(freshProfile);
                    c.originalProfile = angular.copy(c.data.profile);
                    c.normalizeProfile();

                    c.isEditing = false;
                    c.formError = '';

                    notify('success', message || 'Your profile has been updated successfully.');

                } else {

                    restoreProfile(snapshot);

                    c.formError = error || message || 'Unable to update your profile.';
                    notify('error', c.formError);
                }
            },

            function() {

                c.isSaving = false;
                cleanRequest(['profileUpdate']);
                restoreProfile(snapshot);

                c.formError = 'Unable to connect to the server. Please try again.';
                notify('error', c.formError);
            }
        );
    };


    /* =========================================================
       RESUME UPLOAD
       The file input is created here (no inline onchange and no
       angular.element().scope(), which does not work in Service
       Portal when debug info is disabled).
       ========================================================= */

    function getResumeInput() {

        if (resumeInputEl) {
            return resumeInputEl;
        }

        resumeInputEl = document.createElement('input');
        resumeInputEl.type = 'file';
        resumeInputEl.accept = '.pdf,.doc,.docx';
        resumeInputEl.style.display = 'none';

        resumeInputEl.addEventListener('change', function() {

            var file = resumeInputEl.files && resumeInputEl.files.length
                ? resumeInputEl.files[0]
                : null;

            if (file) {
                $scope.$applyAsync(function() {
                    c.processResumeFile(file);
                });
            }

            resumeInputEl.value = '';   // allows picking the same file again
        });

        document.body.appendChild(resumeInputEl);

        return resumeInputEl;
    }

    c.triggerResumeUpload = function() {

        if (!isStudent()) {
            notify('error', 'Only students can upload a resume.');
            return;
        }

        if (!c.isEditing) {
            notify('error', 'Please click Edit Profile before uploading your resume.');
            return;
        }

        if (c.isUploadingResume) { return; }

        getResumeInput().click();
    };

    c.processResumeFile = function(file) {

        var fileName = file.name || '';

        if (ALLOWED_EXT.indexOf(getExt(fileName)) === -1) {
            notify('error', 'Only PDF, DOC, and DOCX files are allowed.');
            return;
        }

        if (file.size > MAX_RESUME_BYTES) {
            notify('error', 'Resume size must be less than 3 MB.');
            return;
        }

        c.showSuccess = false;
        c.showError = false;
        c.isUploadingResume = true;

        var reader = new FileReader();

        reader.onload = function(event) {

            $scope.$applyAsync(function() {

                var dataUrl = event.target.result || '';
                var commaIndex = dataUrl.indexOf(',');

                if (commaIndex === -1) {
                    c.isUploadingResume = false;
                    notify('error', 'Unable to read the selected resume.');
                    return;
                }

                var snapshot = angular.copy(c.data.profile);

                callServer('upload_resume', {

                    resumeFile: {
                        fileName: fileName,
                        contentType: file.type || 'application/octet-stream',
                        size: file.size,
                        base64: dataUrl.substring(commaIndex + 1)
                    }

                }).then(

                    function(result) {

                        // read everything from the response FIRST
                        var success = (result.success === true);
                        var freshProfile = result.profile;
                        var uploadedName = result.resumeName || '';
                        var uploadedId = result.resumeAttachmentId || '';
                        var message = result.message;
                        var error = result.error;

                        c.isUploadingResume = false;
                        cleanRequest(['resumeFile']);

                        if (success) {

                            // 1) take the resume keys from the reloaded profile
                            mergeProfile(freshProfile, RESUME_KEYS, snapshot);

                            // 2) guarantee the uploaded file is shown, even if the reload missed it
                            if (uploadedName) {

                                var p = c.data.profile;

                                p.resume = uploadedName;

                                if (uploadedId) {
                                    p.resumeAttachmentId = uploadedId;
                                    p.resumeUrl = '/sys_attachment.do?sys_id=' + uploadedId;
                                }

                                if (c.originalProfile) {
                                    c.originalProfile.resume = p.resume;
                                    c.originalProfile.resumeAttachmentId = p.resumeAttachmentId;
                                    c.originalProfile.resumeUrl = p.resumeUrl;
                                }
                            }

                            // old cached preview is no longer valid
                            clearCachedResume();

                            notify('success', message || 'Resume uploaded successfully.');

                        } else {

                            restoreProfile(snapshot);
                            notify('error', error || message || 'Resume upload failed.');
                        }
                    },

                    function() {

                        c.isUploadingResume = false;
                        cleanRequest(['resumeFile']);
                        restoreProfile(snapshot);

                        notify('error', 'Unable to upload the resume. Please try again.');
                    }
                );
            });
        };

        reader.onerror = function() {

            $scope.$applyAsync(function() {
                c.isUploadingResume = false;
                notify('error', 'Unable to read the selected resume.');
            });
        };

        reader.readAsDataURL(file);
    };


    /* =========================================================
       RESUME PREVIEW / DOWNLOAD
       The server sends the file as base64. It is turned into a
       Blob here, so it opens inline without depending on
       attachment ACLs or download headers.
       ========================================================= */

    function base64ToBlob(base64, contentType) {

        var binary = window.atob(String(base64).replace(/\s/g, ''));
        var length = binary.length;
        var bytes = new Uint8Array(length);

        for (var i = 0; i < length; i++) {
            bytes[i] = binary.charCodeAt(i);
        }

        return new Blob([bytes], { type: contentType || 'application/octet-stream' });
    }

    function currentResumeKey() {

        var p = c.data && c.data.profile ? c.data.profile : {};

        return (p.resumeAttachmentId || '') + '|' + (p.resume || '');
    }

    function clearCachedResume() {

        if (cachedResume && cachedResume.blobUrl) {
            window.URL.revokeObjectURL(cachedResume.blobUrl);
        }

        cachedResume = null;
        c.resumePreview = null;
        c.showResumePreview = false;
    }

    /*
     * Loads the resume (from cache or from the server) and hands it to callback.
     */
    function loadResumeFile(callback) {

        if (cachedResume && cachedResume.key === currentResumeKey()) {
            callback(cachedResume);
            return;
        }

        if (c.isLoadingResume) { return; }

        c.isLoadingResume = true;

        var snapshot = angular.copy(c.data.profile);

        callServer('get_resume').then(

            function(result) {

                // read first, clean afterwards
                var success = (result.success === true);
                var file = result.resumePreview;
                var error = result.error || result.message;

                c.isLoadingResume = false;
                cleanRequest(['resumePreview']);
                restoreProfile(snapshot);       // keep any unsaved edits

                if (!success || !file || !file.base64) {
                    notify('error', error || 'Unable to open the resume.');
                    return;
                }

                try {

                    var blob = base64ToBlob(file.base64, file.contentType);
                    var blobUrl = window.URL.createObjectURL(blob);

                    clearCachedResume();

                    cachedResume = {
                        key: currentResumeKey(),
                        fileName: file.fileName,
                        contentType: file.contentType,
                        blobUrl: blobUrl,
                        safeUrl: $sce.trustAsResourceUrl(blobUrl),
                        isPdf: getExt(file.fileName) === 'pdf'
                    };

                    callback(cachedResume);

                } catch (e) {
                    notify('error', 'The resume file could not be displayed.');
                }
            },

            function() {

                c.isLoadingResume = false;
                cleanRequest(['resumePreview']);
                restoreProfile(snapshot);

                notify('error', 'Unable to connect to the server. Please try again.');
            }
        );
    }

    c.previewResume = function() {

        if (!c.data.profile || !c.data.profile.resume) {
            notify('error', 'No resume found. Please upload your resume first.');
            return;
        }

        loadResumeFile(function(file) {
            c.resumePreview = file;
            c.showResumePreview = true;
        });
    };

    c.downloadResume = function() {

        if (!c.data.profile || !c.data.profile.resume) {
            notify('error', 'No resume found. Please upload your resume first.');
            return;
        }

        loadResumeFile(function(file) {

            var link = document.createElement('a');

            link.href = file.blobUrl;
            link.download = file.fileName;
            link.style.display = 'none';

            document.body.appendChild(link);
            link.click();
            document.body.removeChild(link);
        });
    };

    c.closeResumePreview = function(event) {

        if (event && event.target !== event.currentTarget) { return; }

        c.showResumePreview = false;
    };


    /* =========================================================
       ADD SKILLS
       ========================================================= */

    c.openAddSkill = function() {

        if (!isStudent()) { return; }

        c.selectedSkillIds = [];
        c.skillCatalogSearch = '';
        c.addSkillError = '';
        c.addSkillSuccess = '';
        c.isAddingSkills = false;
        c.showAddSkillModal = true;
    };

    c.openSkillModal = function() { c.openAddSkill(); };   // HTML compatibility

    c.closeAddSkill = function(event) {

        if (event && event.target !== event.currentTarget) { return; }
        if (c.isAddingSkills) { return; }

        c.showAddSkillModal = false;
        c.selectedSkillIds = [];
        c.skillCatalogSearch = '';
        c.addSkillError = '';
        c.addSkillSuccess = '';
    };

    c.isExistingSkill = function(sysId) {

        var list = (c.data && c.data.profile && c.data.profile.skillList) ? c.data.profile.skillList : [];

        for (var i = 0; i < list.length; i++) {
            if (String(list[i].sys_id) === String(sysId)) {
                return true;
            }
        }

        return false;
    };

    c.isSkillSelected = function(sysId) {
        return c.selectedSkillIds.indexOf(String(sysId)) !== -1;
    };

    c.toggleSkillSelection = function(skill, event) {

        if (event) { event.stopPropagation(); }

        if (!skill || c.isExistingSkill(skill.sys_id) || c.isAddingSkills) { return; }

        var id = String(skill.sys_id);
        var index = c.selectedSkillIds.indexOf(id);

        if (index === -1) {
            c.selectedSkillIds.push(id);
        } else {
            c.selectedSkillIds.splice(index, 1);
        }
    };

    c.addSelectedSkills = function() {

        if (c.isAddingSkills) { return; }

        if (!isStudent()) {
            c.addSkillError = 'Only students can add skills.';
            return;
        }

        if (!c.selectedSkillIds.length) {
            c.addSkillError = 'Please select at least one skill.';
            return;
        }

        c.addSkillError = '';
        c.addSkillSuccess = '';
        c.isAddingSkills = true;

        var snapshot = angular.copy(c.data.profile);

        callServer('add_skills', {

            selectedSkillIds: angular.copy(c.selectedSkillIds)

        }).then(

            function(result) {

                var success = (result.success === true && result.skillsAdded === true);
                var freshProfile = result.profile;
                var message = result.message;
                var error = result.error;

                c.isAddingSkills = false;
                cleanRequest(['selectedSkillIds']);

                if (success) {

                    mergeProfile(freshProfile, SKILL_KEYS, snapshot);

                    c.addSkillSuccess = message || 'Selected skills were added successfully.';
                    c.selectedSkillIds = [];

                    $timeout(function() {
                        c.showAddSkillModal = false;
                        c.addSkillSuccess = '';
                    }, 900);

                } else {

                    restoreProfile(snapshot);
                    c.addSkillError = error || message || 'Unable to add the selected skills.';
                }
            },

            function() {

                c.isAddingSkills = false;
                cleanRequest(['selectedSkillIds']);
                restoreProfile(snapshot);

                c.addSkillError = 'Unable to connect to the server. Please try again.';
            }
        );
    };


    /* =========================================================
       REMOVE SKILL
       ========================================================= */

    c.removeSkill = function(skill, event) {

        if (event) {
            event.preventDefault();
            event.stopPropagation();
        }

        if (c.isRemovingSkill) { return; }

        if (!isStudent()) {
            notify('error', 'Only students can remove skills.');
            return;
        }

        if (!skill || !skill.sys_id) {
            notify('error', 'Invalid skill selected.');
            return;
        }

        c.isRemovingSkill = true;

        var snapshot = angular.copy(c.data.profile);

        callServer('remove_skill', {

            skillId: String(skill.sys_id).trim()

        }).then(

            function(result) {

                var success = (result.success === true && result.skillRemoved === true);
                var freshProfile = result.profile;
                var message = result.message;
                var error = result.error;

                c.isRemovingSkill = false;
                cleanRequest(['skillId']);

                if (success) {

                    mergeProfile(freshProfile, SKILL_KEYS, snapshot);
                    notify('success', message || 'Skill removed successfully.');

                } else {

                    restoreProfile(snapshot);
                    notify('error', error || message || 'Unable to remove the skill.');
                }
            },

            function() {

                c.isRemovingSkill = false;
                cleanRequest(['skillId']);
                restoreProfile(snapshot);

                notify('error', 'Unable to connect to the server. Please try again.');
            }
        );
    };


    /* =========================================================
       REQUEST A NEW SKILL
       ========================================================= */

    c.openSkillRequest = function() {

        if (!isStudent()) { return; }

        c.skillRequest = { requestedTerm: '', reason: '' };
        c.skillRequestError = '';
        c.skillRequestSuccess = '';
        c.isSubmittingSkillRequest = false;
        c.showSkillRequestModal = true;
    };

    c.openRequestSkillModal = function() { c.openSkillRequest(); };   // HTML compatibility

    c.closeSkillRequest = function(event) {

        if (event && event.target !== event.currentTarget) { return; }
        if (c.isSubmittingSkillRequest) { return; }

        c.showSkillRequestModal = false;
        c.skillRequestError = '';
        c.skillRequestSuccess = '';
    };

    c.submitSkillRequest = function() {

        if (c.isSubmittingSkillRequest) { return; }

        if (!isStudent()) {
            c.skillRequestError = 'Only students can request a skill.';
            return;
        }

        var term = String((c.skillRequest && c.skillRequest.requestedTerm) || '').trim();
        var reason = String((c.skillRequest && c.skillRequest.reason) || '').trim();

        if (!term) {
            c.skillRequestError = 'Please enter a skill name.';
            return;
        }

        if (term.length > 100) {
            c.skillRequestError = 'Skill name cannot exceed 100 characters.';
            return;
        }

        c.skillRequestError = '';
        c.skillRequestSuccess = '';
        c.isSubmittingSkillRequest = true;

        var snapshot = angular.copy(c.data.profile);

        callServer('request_skill', {

            skillRequest: { requestedTerm: term, reason: reason }

        }).then(

            function(result) {

                var success = (result.success === true && result.skillRequestCreated === true);
                var message = result.message;
                var error = result.error;

                c.isSubmittingSkillRequest = false;
                cleanRequest(['skillRequest']);
                restoreProfile(snapshot);

                if (success) {

                    c.skillRequestSuccess = message || 'Skill request submitted successfully.';

                    $timeout(function() {
                        c.showSkillRequestModal = false;
                        c.skillRequestSuccess = '';
                    }, 1400);

                } else {

                    c.skillRequestError = error || message || 'Unable to submit the skill request.';
                }
            },

            function() {

                c.isSubmittingSkillRequest = false;
                cleanRequest(['skillRequest']);
                restoreProfile(snapshot);

                c.skillRequestError = 'Unable to connect to the server. Please try again.';
            }
        );
    };


    /* =========================================================
       ALERTS
       ========================================================= */

    c.closeAlert = function(type) {

        if (type === 'success') { c.showSuccess = false; }
        if (type === 'error')   { c.showError = false; }
    };


    /* =========================================================
       NORMALIZE PROFILE
       ========================================================= */

    c.normalizeProfile = function() {

        if (!c.data) { c.data = {}; }
        if (!c.data.profile) { c.data.profile = {}; }

        var p = c.data.profile;

        var textFields = [
            'fullName', 'studentId', 'registerNumber', 'email', 'mobile', 'gender',
            'fatherName', 'fatherMobile', 'address', 'language', 'alternateEmail',
            'collegeName', 'college', 'branch', 'cgpa', 'backlogs', 'currentYear',
            'passingYear', 'skills', 'git', 'linkedin', 'resume', 'resumeUrl',
            'resumeAttachmentId', 'eligible', 'eligibility', 'placementStatus',
            'username', 'title', 'department', 'company', 'location', 'manager',
            'role', 'roleDescription', 'status', 'createdOn'
        ];

        for (var i = 0; i < textFields.length; i++) {
            if (p[textFields[i]] === null || p[textFields[i]] === undefined) {
                p[textFields[i]] = '';
            }
        }

        if (p.completion === null || p.completion === undefined) { p.completion = 0; }
        if (p.eligibleDrives === null || p.eligibleDrives === undefined) { p.eligibleDrives = 0; }

        if (!angular.isArray(p.skillList))       { p.skillList = []; }
        if (!angular.isArray(p.skillCatalog))    { p.skillCatalog = []; }
        if (!angular.isArray(p.genderChoices))   { p.genderChoices = []; }
        if (!angular.isArray(p.languageChoices)) { p.languageChoices = []; }

        if (p.isStudent === undefined)     { p.isStudent = false; }
        if (p.isOfficer === undefined)     { p.isOfficer = false; }
        if (p.isAdmin === undefined)       { p.isAdmin = false; }
        if (p.isInterviewer === undefined) { p.isInterviewer = false; }

        if (!p.statistics || typeof p.statistics !== 'object') { p.statistics = {}; }

        var stats = ['companies', 'students', 'drives', 'applications',
                     'interviews', 'selections', 'offers', 'pending'];

        for (var j = 0; j < stats.length; j++) {
            if (p.statistics[stats[j]] === null || p.statistics[stats[j]] === undefined) {
                p.statistics[stats[j]] = 0;
            }
        }
    };


    /* =========================================================
       CLEANUP
       ========================================================= */

    $scope.$on('$destroy', function() {

        if (resumeInputEl && resumeInputEl.parentNode) {
            resumeInputEl.parentNode.removeChild(resumeInputEl);
        }

        resumeInputEl = null;

        if (cachedResume && cachedResume.blobUrl) {
            window.URL.revokeObjectURL(cachedResume.blobUrl);
        }

        if (alertTimer) {
            $timeout.cancel(alertTimer);
        }
    });


    /* =========================================================
       INIT
       ========================================================= */

    c.normalizeProfile();

    if (c.data && c.data.error && !c.data.success) {
        notify('error', c.data.error);
    }

};

sp_widget.css:
/* =========================================================
   NEXORA — MY PROFILE
   COMPLETE CSS
   MATCHED TO CURRENT HTML EXACTLY
   ========================================================= */

.nexora-profile-page {
    width: 85vw;
    min-height: 100vh;
    padding: 70px;
    box-sizing: border-box;
    background: #ffffff;
    color: #172b3f;
    font-family: "Inter", -apple-system, BlinkMacSystemFont,
                 "Segoe UI", Roboto, Arial, sans-serif;
}


/* =========================================================
   PROFILE HERO
   ========================================================= */

.nx-profile-hero {
    position: relative;
    width: 100%;
    min-height: 220px;
    padding: 34px 38px;
    box-sizing: border-box;
    border-radius: 22px;
    overflow: hidden;

    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 30px;

    background:
        radial-gradient(
            circle at 88% 15%,
            rgba(255,107,91,.18),
            transparent 30%
        ),
        linear-gradient(
            135deg,
            #17334b 0%,
            #20435d 100%
        );

    color: #fff;
    box-shadow: 0 18px 45px rgba(23,51,75,.16);
}

.nx-profile-hero::before {
    content: "";
    position: absolute;
    width: 330px;
    height: 330px;
    right: -120px;
    top: -175px;
    border: 1px solid rgba(255,255,255,.08);
    border-radius: 50%;
    pointer-events: none;
}

.nx-profile-hero::after {
    content: "";
    position: absolute;
    width: 220px;
    height: 220px;
    right: 100px;
    bottom: -175px;
    border: 1px solid rgba(255,255,255,.06);
    border-radius: 50%;
    pointer-events: none;
}


/* =========================================================
   HERO LEFT
   ========================================================= */

.nx-hero-left {
    position: relative;
    z-index: 2;

    display: flex;
    align-items: center;
    gap: 24px;

    min-width: 0;
    flex: 1;
}


/* =========================================================
   AVATAR
   ========================================================= */

.nx-avatar {
    width: 96px;
    height: 96px;
    min-width: 96px;

    border-radius: 24px;

    display: flex;
    align-items: center;
    justify-content: center;

    overflow: hidden;

    background: linear-gradient(
        145deg,
        #ff806f,
        #ff5f50
    );

    border: 4px solid rgba(255,255,255,.22);

    color: #fff;
    font-size: 34px;
    font-weight: 800;

    box-shadow: 0 12px 28px rgba(0,0,0,.20);
}

.nx-avatar img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    display: block;
}


/* =========================================================
   HERO CONTENT
   ========================================================= */

.nx-hero-content {
    min-width: 0;
    flex: 1;
}

.nx-eyebrow {
    display: flex;
    align-items: center;
    gap: 8px;

    margin-bottom: 8px;

    color: #ffafa6;
    font-size: 10px;
    font-weight: 800;
    letter-spacing: 1.8px;
}

.nx-eyebrow-dot {
    width: 7px;
    height: 7px;
    border-radius: 50%;
    background: #ff6b5b;
    box-shadow: 0 0 0 4px rgba(255,107,91,.10);
}

.nx-hero-content h1 {
    margin: 0;

    color: #fff;

    font-size: 31px;
    line-height: 1.15;
    font-weight: 800;

    letter-spacing: -.5px;

    word-break: break-word;
}

.nx-role-text {
    margin: 10px 0 0;

    color: #c8d7e1;

    font-size: 12px;
    line-height: 1.55;
}

.nx-hero-meta {
    display: flex;
    align-items: center;
    flex-wrap: wrap;
    gap: 9px 17px;

    margin-top: 13px;
}

.nx-hero-meta span {
    display: inline-flex;
    align-items: center;
    gap: 7px;

    color: #d5e1e8;

    font-size: 10px;
}

.nx-hero-meta i {
    color: #ff8c80;
}


/* =========================================================
   HERO ACTION
   ========================================================= */

.nx-hero-actions {
    position: relative;
    z-index: 3;

    flex-shrink: 0;
}

.nx-edit-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 8px;

    padding: 11px 16px;

    border: 1px solid rgba(255,255,255,.25);
    border-radius: 10px;

    background: rgba(255,255,255,.10);

    color: #fff;

    font-family: inherit;
    font-size: 11px;
    font-weight: 700;

    cursor: pointer;

    transition: .2s ease;

    backdrop-filter: blur(8px);
}

.nx-edit-btn:hover {
    background: #ff6b5b;
    border-color: #ff6b5b;

    transform: translateY(-1px);
}


/* =========================================================
   ALERTS
   ========================================================= */

.nx-alert {
    width: 100%;
    box-sizing: border-box;

    margin-top: 20px;
    padding: 14px 17px;

    border-radius: 12px;

    display: flex;
    align-items: center;
    gap: 12px;

    border: 1px solid;
}

.nx-alert-success {
    background: #effaf5;
    border-color: #bde8d1;
    color: #176b46;
}

.nx-alert-error {
    background: #fff3f2;
    border-color: #f1c3bd;
    color: #a13d34;
}

.nx-alert-icon {
    width: 32px;
    height: 32px;
    min-width: 32px;

    border-radius: 9px;

    display: flex;
    align-items: center;
    justify-content: center;

    background: rgba(255,255,255,.8);
}

.nx-alert > div:nth-child(2) {
    min-width: 0;
}

.nx-alert strong {
    display: block;
    font-size: 12px;
    font-weight: 800;
}

.nx-alert span {
    display: block;
    margin-top: 3px;
    font-size: 11px;
}


/* =========================================================
   STUDENT MAIN AREA
   ========================================================= */

.nexora-profile-page > div[ng-if="c.data.profile.isStudent"] {
    width: 100%;
    max-width: 1500px;
    margin: 0 auto;
}


/* =========================================================
   PROFILE COMPLETION
   ========================================================= */

.nx-completion-card {
    width: 100%;
    margin-top: 24px;
    padding: 21px 25px;

    box-sizing: border-box;

    border: 1px solid #e4e9ef;
    border-radius: 19px;

    background: #fff;

    box-shadow: 0 8px 28px rgba(28,45,60,.045);

    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 25px;
}

.nx-completion-main {
    min-width: 0;
    flex: 1;

    display: flex;
    align-items: center;
    gap: 14px;
}

.nx-completion-icon {
    width: 46px;
    height: 46px;
    min-width: 46px;

    border-radius: 13px;

    display: flex;
    align-items: center;
    justify-content: center;

    background: #fff0ee;
    color: #ff6b5b;

    font-size: 17px;
}

.nx-completion-text {
    min-width: 0;
    flex: 1;
}

.nx-completion-title-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 15px;
}

.nx-completion-title-row h3 {
    margin: 0;

    color: #172b3f;

    font-size: 14px;
    font-weight: 800;
}

.nx-completion-title-row strong {
    color: #ff6b5b;
    font-size: 16px;
    font-weight: 800;
}

.nx-completion-text p {
    margin: 4px 0 0;

    color: #8794a1;

    font-size: 10px;
    line-height: 1.5;
}

.nx-progress-track {
    width: 100%;
    height: 7px;

    margin-top: 11px;

    border-radius: 20px;

    background: #edf0f3;

    overflow: hidden;
}

.nx-progress-fill {
    height: 100%;

    min-width: 0;

    border-radius: inherit;

    background: linear-gradient(
        90deg,
        #ff6b5b,
        #ff8b7d
    );

    transition: width .4s ease;
}

.nx-completion-status {
    flex-shrink: 0;

    display: inline-flex;
    align-items: center;
    gap: 7px;

    padding: 8px 11px;

    border-radius: 8px;

    background: #fff5df;
    color: #a66d17;

    font-size: 9px;
    font-weight: 800;
}

.nx-completion-status.is-complete {
    background: #effaf4;
    color: #27794f;
}


/* =========================================================
   GENERIC CARD
   ========================================================= */

.nx-card {
    width: 100%;

    margin-top: 24px;

    box-sizing: border-box;

    background: #fff;

    border: 1px solid #e4e9ef;
    border-radius: 19px;

    box-shadow: 0 8px 28px rgba(28,45,60,.045);

    overflow: hidden;
}


/* =========================================================
   CARD HEADER
   ========================================================= */

.nx-card-header {
    min-height: 75px;

    padding: 18px 25px;

    box-sizing: border-box;

    border-bottom: 1px solid #edf0f3;

    display: flex;
    align-items: center;
    justify-content: space-between;

    gap: 15px;
}

.nx-card-title-wrap {
    min-width: 0;

    display: flex;
    align-items: center;
    gap: 13px;
}

.nx-card-title-wrap > div:last-child {
    min-width: 0;
}

.nx-card-title-wrap h2 {
    margin: 0;

    color: #172b3f;

    font-size: 16px;
    font-weight: 800;
}

.nx-card-title-wrap p {
    margin: 4px 0 0;

    color: #8794a1;

    font-size: 10px;
}


/* =========================================================
   SECTION ICON
   ========================================================= */

.nx-section-icon {
    width: 43px;
    height: 43px;
    min-width: 43px;

    border-radius: 12px;

    display: flex;
    align-items: center;
    justify-content: center;

    background: #fff0ee;
    color: #ff6b5b;

    font-size: 17px;
}

.nx-section-icon.staff {
    background: #eef4f8;
    color: #315b73;
}


/* =========================================================
   SECTION BADGE
   ========================================================= */

.nx-section-badge {
    flex-shrink: 0;

    padding: 6px 9px;

    border-radius: 7px;

    background: #f2f5f7;
    color: #72818d;

    font-size: 8px;
    font-weight: 800;

    letter-spacing: .7px;
}


/* =========================================================
   FIELDS GRID
   ========================================================= */

.nx-fields-grid {
    padding: 25px;

    display: grid;
    grid-template-columns: repeat(2,minmax(0,1fr));

    gap: 19px;
}

.nx-field {
    min-width: 0;
}

.nx-field-full {
    grid-column: 1 / -1;
}

.nx-field > label {
    display: block;

    margin-bottom: 7px;

    color: #687886;

    font-size: 11px;
    font-weight: 700;
}


/* =========================================================
   INPUT WRAP
   ========================================================= */

.nx-input-wrap {
    position: relative;
}

.nx-input-wrap > i {
    position: absolute;

    left: 13px;
    top: 50%;

    transform: translateY(-50%);

    z-index: 2;

    color: #99a6b1;

    font-size: 12px;

    pointer-events: none;
}

.nx-input-wrap input,
.nx-input-wrap textarea {
    width: 100%;

    box-sizing: border-box;

    border: 1px solid #e0e6eb;
    border-radius: 10px;

    background: #f9fafb;

    color: #24384a;

    padding: 11px 13px 11px 36px;

    font-family: inherit;
    font-size: 12px;

    outline: none;

    transition: .2s ease;
}

.nx-input-wrap textarea {
    min-height: 90px;

    resize: vertical;

    line-height: 1.5;

    padding-top: 12px;
}

.nx-input-wrap input:focus,
.nx-input-wrap textarea:focus {
    border-color: #ff9185;

    background: #fff;

    box-shadow:
        0 0 0 3px rgba(255,107,91,.08);
}

.nx-input-wrap input:disabled,
.nx-input-wrap textarea:disabled {
    opacity: 1;

    cursor: default;

    color: #3b5264;

    background: #f8fafb;
}


/* =========================================================
   ACADEMIC HIGHLIGHT
   ========================================================= */

.nx-academic-highlight {
    margin: 22px 25px 0;

    padding: 18px;

    border-radius: 14px;

    background:
        linear-gradient(
            135deg,
            #f7fafc,
            #f2f6f9
        );

    border: 1px solid #e2e9ee;

    display: grid;
    grid-template-columns: repeat(4,1fr);

    align-items: center;
}

.nx-academic-item {
    text-align: center;
}

.nx-academic-label {
    display: block;

    margin-bottom: 6px;

    color: #8a97a2;

    font-size: 9px;
    font-weight: 800;

    letter-spacing: .7px;
}

.nx-academic-item strong {
    color: #20394c;

    font-size: 19px;
    font-weight: 800;
}

.nx-academic-divider {
    width: 1px;
    height: 35px;

    justify-self: center;

    background: #dce4e9;
}

.academic-fields {
    padding-top: 20px;
}


/* =========================================================
   READONLY BOX
   ========================================================= */

.nx-readonly-box {
    min-height: 42px;

    box-sizing: border-box;

    padding: 10px 13px;

    border: 1px solid #e2e8ed;
    border-radius: 10px;

    background: #f8fafb;

    display: flex;
    align-items: center;
    gap: 10px;
}

.nx-readonly-box i {
    color: #8999a5;

    font-size: 12px;
}

.nx-readonly-box span {
    min-width: 0;

    color: #405667;

    font-size: 11px;
    font-weight: 600;

    word-break: break-word;
}


/* =========================================================
   PROFESSIONAL SECTION
   ========================================================= */

.nx-professional-section {
    padding: 25px;
}

.nx-subheading {
    display: flex;
    align-items: center;
    justify-content: space-between;

    gap: 15px;
}

.nx-subheading > div:first-child {
    min-width: 0;

    display: flex;
    align-items: center;
    gap: 11px;
}

.nx-subheading > div:first-child > div {
    min-width: 0;
}

.nx-sub-icon {
    width: 39px;
    height: 39px;
    min-width: 39px;

    border-radius: 10px;

    display: flex;
    align-items: center;
    justify-content: center;

    background: #eef5f8;
    color: #315b73;

    font-size: 14px;
}

.nx-sub-icon.resume {
    background: #fff0ee;
    color: #e85849;
}

.nx-subheading strong {
    display: block;

    color: #263d50;

    font-size: 12px;
    font-weight: 800;
}

.nx-subheading small {
    display: block;

    margin-top: 3px;

    color: #8b98a3;

    font-size: 9px;
}


/* =========================================================
   ADD SKILL BUTTON
   ========================================================= */

.nx-small-btn,
.nx-request-skill-btn {
    display: inline-flex;

    align-items: center;
    justify-content: center;

    gap: 7px;

    padding: 8px 12px;

    border-radius: 8px;

    font-family: inherit;

    font-size: 10px;
    font-weight: 800;

    cursor: pointer;

    transition: .2s ease;
}

.nx-small-btn {
    border: 1px solid #d6e2e9;

    background: #eef5f8;

    color: #315a71;
}

.nx-small-btn:hover {
    background: #20435d;
    border-color: #20435d;
    color: #fff;

    transform: translateY(-1px);
}


/* =========================================================
   REQUEST SKILL BUTTON
   ========================================================= */

.nx-request-skill-btn {
    border: 1px solid #ffd1cb;

    background: #fff5f3;

    color: #e95c4d;
}

.nx-request-skill-btn:hover {
    background: #ff6b5b;

    border-color: #ff6b5b;

    color: #fff;

    transform: translateY(-1px);
}

.nx-request-skill-btn:active {
    transform: translateY(0);
}


/* =========================================================
   SKILLS
   ========================================================= */

.nx-skills {
    display: flex;

    align-items: center;

    flex-wrap: wrap;

    gap: 8px;

    margin-top: 17px;
}

.nx-skill {
    display: inline-flex;

    align-items: center;

    padding: 8px 11px;

    border-radius: 9px;

    background: #f0f5f8;

    border: 1px solid #dce6ed;

    color: #31546a;

    font-size: 10px;
    font-weight: 700;

    transition: .2s ease;
}

.nx-skill:hover {
    border-color: #c8d7e0;

    background: #eaf1f5;

    transform: translateY(-1px);
}


/* =========================================================
   EMPTY STATE
   ========================================================= */

.nx-empty-state {
    min-height: 70px;

    margin-top: 15px;

    padding: 15px;

    box-sizing: border-box;

    border: 1px dashed #d5dfe6;

    border-radius: 11px;

    background: #fafcfd;

    color: #8996a1;

    display: flex;

    align-items: center;

    justify-content: center;

    gap: 9px;

    font-size: 10px;
}

.nx-empty-state > i {
    color: #9caab5;
}

.nx-empty-state button {
    padding: 6px 9px;

    border: 0;
    border-radius: 7px;

    background: #eef5f8;

    color: #315b73;

    font-family: inherit;

    font-size: 9px;
    font-weight: 800;

    cursor: pointer;
}

.nx-empty-state button:hover {
    background: #20435d;
    color: #fff;
}


/* =========================================================
   LINKS GRID
   ========================================================= */

.nx-links-grid {
    padding: 0 25px 25px;

    display: grid;

    grid-template-columns: repeat(2,minmax(0,1fr));

    gap: 13px;
}

.nx-professional-link {
    min-width: 0;

    padding: 14px;

    box-sizing: border-box;

    border: 1px solid #e5eaf0;

    border-radius: 12px;

    background: #fbfcfd;

    display: flex;

    align-items: center;

    gap: 12px;

    transition: .2s ease;
}

.nx-professional-link:focus-within {
    border-color: #ffaaa1;

    background: #fff;

    box-shadow:
        0 0 0 3px rgba(255,107,91,.06);
}

.nx-link-icon {
    width: 42px;
    height: 42px;
    min-width: 42px;

    border-radius: 11px;

    display: flex;
    align-items: center;
    justify-content: center;

    font-size: 17px;
}

.nx-link-icon.github {
    background: #eef1f3;
    color: #26333d;
}

.nx-link-icon.linkedin {
    background: #edf5fb;
    color: #286d9d;
}

.nx-link-content {
    min-width: 0;
    flex: 1;
}

.nx-link-content label {
    display: block;

    margin-bottom: 6px;

    color: #687886;

    font-size: 10px;
    font-weight: 800;
}

.nx-link-content input {
    width: 100%;

    box-sizing: border-box;

    border: 0;

    background: transparent;

    color: #334c5e;

    font-family: inherit;

    font-size: 11px;

    outline: none;
}

.nx-link-content input::placeholder {
    color: #a0abb4;
}

.nx-link-content input:disabled {
    color: #526979;

    cursor: default;
}


/* =========================================================
   RESUME SECTION
   ========================================================= */

.nx-resume-section {
    padding: 0 25px 25px;
}


/* =========================================================
   RESUME CARD
   ========================================================= */

.nx-resume-card {
    margin-top: 17px;

    padding: 14px;

    box-sizing: border-box;

    border: 1px solid #e3e9ee;

    border-radius: 12px;

    background: #fbfcfd;

    display: flex;

    align-items: center;

    justify-content: space-between;

    gap: 15px;
}

.nx-resume-left {
    min-width: 0;

    display: flex;

    align-items: center;

    gap: 12px;
}

.nx-resume-file-icon {
    width: 44px;
    height: 44px;
    min-width: 44px;

    border-radius: 11px;

    background: #fff0ee;

    color: #e85849;

    display: flex;
    align-items: center;
    justify-content: center;

    font-size: 18px;
}

.nx-resume-info {
    min-width: 0;
}

.nx-resume-info strong {
    display: block;

    max-width: 420px;

    color: #273e50;

    font-size: 11px;
    font-weight: 800;

    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.nx-resume-info span {
    display: block;

    margin-top: 4px;

    color: #8b98a3;

    font-size: 9px;
}

.nx-resume-actions {
    flex-shrink: 0;

    display: flex;

    align-items: center;

    gap: 7px;
}

.nx-resume-view,
.nx-resume-replace {
    display: inline-flex;

    align-items: center;
    justify-content: center;

    gap: 6px;

    padding: 8px 11px;

    border-radius: 8px;

    font-family: inherit;

    font-size: 9px;
    font-weight: 800;

    text-decoration: none;

    cursor: pointer;

    transition: .2s ease;
}

.nx-resume-view {
    border: 1px solid #d8e3e9;

    background: #eef5f8;

    color: #315a71;
}

.nx-resume-view:hover {
    background: #20435d;

    border-color: #20435d;

    color: #fff;

    text-decoration: none;
}

.nx-resume-replace {
    border: 1px solid #ffd1cb;

    background: #fff5f3;

    color: #df5b4d;
}

.nx-resume-replace:hover {
    background: #ff6b5b;

    border-color: #ff6b5b;

    color: #fff;
}


/* =========================================================
   RESUME UPLOAD CARD
   ========================================================= */

.nx-resume-upload-card {
    margin-top: 17px;

    min-height: 80px;

    padding: 15px;

    box-sizing: border-box;

    border: 1px dashed #d5dfe6;

    border-radius: 12px;

    background: #fafcfd;

    display: flex;

    align-items: center;

    gap: 13px;
}

.nx-upload-icon {
    width: 44px;
    height: 44px;
    min-width: 44px;

    border-radius: 11px;

    display: flex;
    align-items: center;
    justify-content: center;

    background: #eef5f8;

    color: #315b73;

    font-size: 18px;
}

.nx-upload-content {
    min-width: 0;

    flex: 1;
}

.nx-upload-content strong {
    display: block;

    color: #2a4153;

    font-size: 11px;
    font-weight: 800;
}

.nx-upload-content span {
    display: block;

    margin-top: 4px;

    color: #8a97a2;

    font-size: 9px;

    line-height: 1.45;
}

.nx-upload-btn {
    flex-shrink: 0;

    display: inline-flex;

    align-items: center;
    justify-content: center;

    gap: 7px;

    padding: 9px 12px;

    border: 0;

    border-radius: 8px;

    background: #ff6b5b;

    color: #fff;

    font-family: inherit;

    font-size: 9px;
    font-weight: 800;

    cursor: pointer;

    box-shadow: 0 5px 12px rgba(255,107,91,.18);

    transition: .2s ease;
}

.nx-upload-btn:hover {
    background: #e95748;

    transform: translateY(-1px);
}

.nx-hidden-file {
    display: none !important;
}


/* =========================================================
   PLACEMENT INFORMATION
   ========================================================= */

.nx-placement-grid {
    padding: 25px;

    display: grid;

    grid-template-columns: repeat(2,minmax(0,1fr));

    gap: 14px;
}

.nx-placement-box {
    padding: 17px;

    border: 1px solid #e5eaf0;

    border-radius: 12px;

    background: #fbfcfd;

    display: flex;

    align-items: center;

    gap: 12px;

    transition: .2s ease;
}

.nx-placement-box:hover {
    background: #fff;

    border-color: #d8e2e9;

    transform: translateY(-1px);
}

.nx-placement-icon {
    width: 42px;
    height: 42px;
    min-width: 42px;

    border-radius: 11px;

    display: flex;
    align-items: center;
    justify-content: center;

    background: #eef5f8;

    color: #315b73;

    font-size: 16px;
}

.nx-placement-icon.eligibility {
    background: #eef9f4;

    color: #27825a;
}

.nx-placement-box span {
    display: block;

    margin-bottom: 5px;

    color: #8996a1;

    font-size: 9px;

    font-weight: 700;
}

.nx-placement-box strong {
    display: block;

    color: #263e50;

    font-size: 13px;

    font-weight: 800;
}


/* =========================================================
   ACCOUNT INFORMATION
   ========================================================= */

.nx-account-grid {
    padding: 25px;

    display: grid;

    grid-template-columns: repeat(3,minmax(0,1fr));

    gap: 13px;
}

.nx-account-item {
    min-width: 0;

    padding: 15px;

    border: 1px solid #e5eaf0;

    border-radius: 12px;

    background: #fbfcfd;

    display: flex;

    align-items: center;

    gap: 11px;
}

.nx-account-icon {
    width: 39px;
    height: 39px;
    min-width: 39px;

    border-radius: 10px;

    background: #eef4f8;

    color: #42667d;

    display: flex;
    align-items: center;
    justify-content: center;

    font-size: 14px;
}

.nx-account-item > div {
    min-width: 0;
}

.nx-account-item small {
    display: block;

    margin-bottom: 4px;

    color: #8996a2;

    font-size: 9px;

    font-weight: 700;
}

.nx-account-item strong {
    display: block;

    color: #20394c;

    font-size: 11px;

    word-break: break-word;
}


/* =========================================================
   SAVE BAR
   ========================================================= */

.nx-save-bar {
    margin-top: 24px;

    padding: 16px 19px;

    border: 1px solid #dce5eb;

    border-radius: 13px;

    background: #fff;

    display: flex;

    align-items: center;

    justify-content: space-between;

    gap: 18px;

    box-shadow: 0 8px 24px rgba(28,45,60,.05);
}

.nx-save-bar > div:first-child {
    min-width: 0;
}

.nx-save-bar strong {
    display: block;

    color: #2a4051;

    font-size: 11px;

    font-weight: 800;
}

.nx-save-bar span {
    display: block;

    margin-top: 4px;

    color: #8a97a2;

    font-size: 9px;
}

.nx-save-actions {
    flex-shrink: 0;

    display: flex;

    align-items: center;

    gap: 8px;
}

.nx-cancel-btn,
.nx-save-btn {
    min-height: 36px;

    padding: 9px 14px;

    border-radius: 8px;

    font-family: inherit;

    font-size: 10px;

    font-weight: 800;

    cursor: pointer;

    transition: .2s ease;
}

.nx-cancel-btn {
    border: 1px solid #dfe5ea;

    background: #fff;

    color: #687987;
}

.nx-cancel-btn:hover {
    background: #f4f7f9;
}

.nx-save-btn {
    border: 0;

    background: #ff6b5b;

    color: #fff;

    box-shadow: 0 5px 12px rgba(255,107,91,.18);
}

.nx-save-btn:hover {
    background: #e95748;

    transform: translateY(-1px);
}


/* =========================================================
   STAFF PROFILE
   ========================================================= */

.nx-staff-profile {
    width: 100%;
    max-width: 1500px;

    margin: 0 auto;
}


/* =========================================================
   STAFF OVERVIEW
   ========================================================= */

.nx-staff-overview {
    overflow: hidden;
}

.nx-staff-info-grid {
    padding: 25px;

    display: grid;

    grid-template-columns: repeat(4,minmax(0,1fr));

    gap: 13px;
}

.nx-staff-info {
    min-width: 0;

    padding: 15px;

    border: 1px solid #e5eaf0;

    border-radius: 12px;

    background: #fbfcfd;

    display: flex;

    align-items: center;

    gap: 11px;

    transition: .2s ease;
}

.nx-staff-info:hover {
    background: #fff;

    transform: translateY(-1px);

    box-shadow: 0 6px 18px rgba(28,45,60,.05);
}

.nx-staff-info-icon {
    width: 39px;
    height: 39px;
    min-width: 39px;

    border-radius: 10px;

    display: flex;
    align-items: center;
    justify-content: center;

    background: #eef4f8;

    color: #42667d;

    font-size: 14px;
}

.nx-staff-info > div {
    min-width: 0;
}

.nx-staff-info small {
    display: block;

    margin-bottom: 4px;

    color: #8996a2;

    font-size: 9px;

    font-weight: 700;
}

.nx-staff-info strong {
    display: block;

    color: #20394c;

    font-size: 11px;

    word-break: break-word;
}


/* =========================================================
   STAFF STATISTICS
   ========================================================= */

.nx-stats-grid {
    padding: 25px;

    display: grid;

    grid-template-columns: repeat(4,minmax(0,1fr));

    gap: 13px;
}

.nx-stat-card {
    min-width: 0;

    padding: 15px;

    border: 1px solid #e5eaf0;

    border-radius: 12px;

    background: #fbfcfd;

    display: flex;

    align-items: center;

    gap: 11px;

    transition: .2s ease;
}

.nx-stat-card:hover {
    transform: translateY(-2px);

    background: #fff;

    box-shadow: 0 7px 18px rgba(25,48,65,.07);
}

.nx-stat-icon {
    width: 39px;
    height: 39px;
    min-width: 39px;

    border-radius: 10px;

    display: flex;
    align-items: center;
    justify-content: center;

    background: #edf5fa;

    color: #38637c;

    font-size: 14px;
}

.nx-stat-card:nth-child(2) .nx-stat-icon {
    background: #eef4f8;
    color: #42667d;
}

.nx-stat-card:nth-child(3) .nx-stat-icon {
    background: #fff0ee;
    color: #e95d4e;
}

.nx-stat-card:nth-child(4) .nx-stat-icon {
    background: #f3effa;
    color: #7556a6;
}

.nx-stat-card:nth-child(5) .nx-stat-icon {
    background: #eef5f8;
    color: #38637c;
}

.nx-stat-card:nth-child(6) .nx-stat-icon {
    background: #eef9f4;
    color: #2c875d;
}

.nx-stat-card:nth-child(7) .nx-stat-icon {
    background: #fff8df;
    color: #ae801e;
}

.nx-stat-card:nth-child(8) .nx-stat-icon {
    background: #fff4e6;
    color: #bd7a22;
}

.nx-stat-card.pending .nx-stat-icon {
    background: #fff4e6;
    color: #bd7a22;
}

.nx-stat-card > div:last-child {
    min-width: 0;
}

.nx-stat-card span {
    display: block;

    margin-bottom: 4px;

    color: #8996a2;

    font-size: 9px;
}

.nx-stat-card strong {
    display: block;

    color: #20394c;

    font-size: 18px;

    font-weight: 800;
}


/* =========================================================
   STAFF ROLE BANNER
   ========================================================= */

.nx-staff-role-banner {
    margin-top: 24px;

    padding: 18px 20px;

    box-sizing: border-box;

    border: 1px solid #dce5eb;

    border-radius: 14px;

    background:
        linear-gradient(
            135deg,
            #f7fafc,
            #eef4f8
        );

    display: flex;

    align-items: center;

    gap: 14px;
}

.nx-role-banner-icon {
    width: 46px;
    height: 46px;
    min-width: 46px;

    border-radius: 12px;

    background: #17334b;

    color: #fff;

    display: flex;
    align-items: center;
    justify-content: center;

    font-size: 17px;
}

.nx-staff-role-banner strong {
    display: block;

    color: #20394c;

    font-size: 13px;

    font-weight: 800;
}

.nx-staff-role-banner p {
    margin: 4px 0 0;

    color: #7f8e9a;

    font-size: 10px;

    line-height: 1.5;
}


/* =========================================================
   MODAL OVERLAY
   ========================================================= */

.nx-modal-overlay {
    position: fixed;

    inset: 0;

    z-index: 99999;

    padding: 20px;

    box-sizing: border-box;

    background: rgba(14,27,39,.66);

    display: flex;

    align-items: center;
    justify-content: center;

    animation: nxModalFade .18s ease;
}

@keyframes nxModalFade {
    from {
        opacity: 0;
    }

    to {
        opacity: 1;
    }
}


/* =========================================================
   MODAL
   ========================================================= */

.nx-modal {
    width: 100%;

    max-width: 520px;

    max-height: calc(100vh - 40px);

    box-sizing: border-box;

    background: #fff;

    border-radius: 18px;

    box-shadow: 0 28px 80px rgba(0,0,0,.25);

    overflow: hidden;

    display: flex;

    flex-direction: column;

    animation: nxModalSlide .2s ease;
}

.nx-request-skill-modal {
    max-width: 560px;
}

@keyframes nxModalSlide {
    from {
        opacity: 0;

        transform:
            translateY(10px)
            scale(.985);
    }

    to {
        opacity: 1;

        transform:
            translateY(0)
            scale(1);
    }
}


/* =========================================================
   MODAL HEADER
   ========================================================= */

.nx-modal-header {
    padding: 20px 22px;

    border-bottom: 1px solid #edf0f3;

    display: flex;

    align-items: flex-start;

    justify-content: space-between;

    gap: 15px;

    flex-shrink: 0;
}

.nx-modal-eyebrow {
    display: block;

    color: #ff6b5b;

    font-size: 9px;

    font-weight: 800;

    letter-spacing: 1.4px;
}

.nx-modal-header h3 {
    margin: 4px 0 0;

    color: #172b3f;

    font-size: 17px;

    font-weight: 800;
}

.nx-modal-close {
    width: 32px;
    height: 32px;

    min-width: 32px;

    border: 0;

    border-radius: 8px;

    background: #f2f5f7;

    color: #72818d;

    cursor: pointer;

    transition: .2s ease;
}

.nx-modal-close:hover {
    background: #fff0ee;

    color: #e95b4d;
}


/* =========================================================
   MODAL BODY
   ========================================================= */

.nx-modal-body {
    padding: 21px 22px;

    overflow-y: auto;

    flex: 1;
}

.nx-modal-body > label {
    display: block;

    margin-bottom: 7px;

    color: #657684;

    font-size: 11px;

    font-weight: 800;
}

.nx-modal-body > input {
    width: 100%;

    height: 42px;

    box-sizing: border-box;

    padding: 0 13px;

    border: 1px solid #dfe5ea;

    border-radius: 10px;

    background: #fafbfc;

    color: #263d50;

    font-family: inherit;

    font-size: 11px;

    outline: none;

    transition: .2s ease;
}

.nx-modal-body > input:focus {
    border-color: #ff8d80;

    background: #fff;

    box-shadow:
        0 0 0 3px rgba(255,107,91,.08);
}


/* =========================================================
   REQUEST SKILL INFO
   ========================================================= */

.nx-request-info {
    margin-bottom: 18px;

    padding: 13px;

    border: 1px solid #f1dfc3;

    border-radius: 11px;

    background: #fffaf1;

    display: flex;

    align-items: center;

    gap: 11px;
}

.nx-request-info-icon {
    width: 39px;
    height: 39px;
    min-width: 39px;

    border-radius: 10px;

    background: #fff0d7;

    color: #bd7a22;

    display: flex;
    align-items: center;
    justify-content: center;

    font-size: 15px;
}

.nx-request-info > div:last-child {
    min-width: 0;
}

.nx-request-info strong {
    display: block;

    color: #674d27;

    font-size: 11px;

    font-weight: 800;
}

.nx-request-info span {
    display: block;

    margin-top: 3px;

    color: #907650;

    font-size: 9px;

    line-height: 1.45;
}


/* =========================================================
   REQUEST INPUT
   ========================================================= */

.nx-request-input-wrap {
    position: relative;

    margin-bottom: 16px;
}

.nx-request-input-wrap > i {
    position: absolute;

    left: 13px;
    top: 50%;

    transform: translateY(-50%);

    color: #97a4ae;

    font-size: 12px;

    pointer-events: none;
}

.nx-request-input-wrap input {
    width: 100%;

    height: 42px;

    box-sizing: border-box;

    padding: 0 13px 0 36px;

    border: 1px solid #dfe5ea;

    border-radius: 10px;

    background: #fafbfc;

    color: #263d50;

    font-family: inherit;

    font-size: 11px;

    outline: none;

    transition: .2s ease;
}

.nx-request-input-wrap input:focus {
    border-color: #ff8d80;

    background: #fff;

    box-shadow:
        0 0 0 3px rgba(255,107,91,.08);
}


/* =========================================================
   REQUEST MESSAGE
   ========================================================= */

.nx-request-message-label {
    display: flex !important;

    align-items: center;

    justify-content: space-between;

    gap: 10px;
}

.nx-request-message-label span {
    color: #9aa5ad;

    font-size: 8px;

    font-weight: 600;
}

.nx-request-textarea {
    width: 100%;

    box-sizing: border-box;

    min-height: 95px;

    padding: 11px 13px;

    border: 1px solid #dfe5ea;

    border-radius: 10px;

    background: #fafbfc;

    color: #263d50;

    font-family: inherit;

    font-size: 11px;

    line-height: 1.5;

    resize: vertical;

    outline: none;

    transition: .2s ease;
}

.nx-request-textarea:focus {
    border-color: #ff8d80;

    background: #fff;

    box-shadow:
        0 0 0 3px rgba(255,107,91,.08);
}

.nx-request-textarea::placeholder,
.nx-request-input-wrap input::placeholder,
.nx-modal-body > input::placeholder {
    color: #a0abb4;
}


/* =========================================================
   REQUEST NOTE
   ========================================================= */

.nx-request-note {
    margin-top: 13px;

    padding: 10px 12px;

    border-radius: 9px;

    background: #f3f7fa;

    color: #728390;

    display: flex;

    align-items: flex-start;

    gap: 8px;

    font-size: 9px;

    line-height: 1.45;
}

.nx-request-note i {
    color: #52758c;

    margin-top: 1px;
}


/* =========================================================
   MODAL FOOTER
   ========================================================= */

.nx-modal-footer {
    min-height: 61px;

    box-sizing: border-box;

    padding: 13px 22px;

    border-top: 1px solid #edf0f3;

    display: flex;

    align-items: center;

    justify-content: flex-end;

    gap: 8px;

    flex-shrink: 0;
}

.nx-modal-cancel,
.nx-modal-primary {
    min-height: 36px;

    padding: 9px 14px;

    border-radius: 8px;

    font-family: inherit;

    font-size: 10px;

    font-weight: 800;

    cursor: pointer;

    transition: .2s ease;
}

.nx-modal-cancel {
    border: 1px solid #dfe5ea;

    background: #fff;

    color: #687987;
}

.nx-modal-cancel:hover {
    background: #f4f7f9;
}

.nx-modal-primary {
    border: 0;

    background: #ff6b5b;

    color: #fff;

    box-shadow: 0 5px 12px rgba(255,107,91,.18);
}

.nx-modal-primary:hover:not(:disabled) {
    background: #e95748;

    transform: translateY(-1px);
}

.nx-modal-primary:disabled {
    opacity: .5;

    cursor: not-allowed;

    box-shadow: none;
}

.nx-request-submit-btn {
    min-width: 125px;
}


/* =========================================================
   MODAL SCROLLBAR
   ========================================================= */

.nx-modal-body::-webkit-scrollbar {
    width: 5px;
}

.nx-modal-body::-webkit-scrollbar-track {
    background: #f5f7f9;
}

.nx-modal-body::-webkit-scrollbar-thumb {
    background: #cbd5dc;

    border-radius: 10px;
}


/* =========================================================
   RESPONSIVE — 1150px
   ========================================================= */

@media (max-width: 1150px) {

    .nexora-profile-page {
        padding: 30px 28px 60px;
    }

    .nx-staff-info-grid {
        grid-template-columns: repeat(2,minmax(0,1fr));
    }

    .nx-stats-grid {
        grid-template-columns: repeat(2,minmax(0,1fr));
    }

    .nx-account-grid {
        grid-template-columns: repeat(2,minmax(0,1fr));
    }

    .nx-academic-highlight {
        grid-template-columns: repeat(2,1fr);

        gap: 15px;
    }

    .nx-academic-divider {
        display: none;
    }
}


/* =========================================================
   RESPONSIVE — 900px
   ========================================================= */

@media (max-width: 900px) {

    .nx-profile-hero {
        align-items: flex-start;

        flex-direction: column;
    }

    .nx-hero-actions {
        width: 100%;
    }

    .nx-hero-actions .nx-edit-btn {
        width: auto;
    }

    .nx-staff-info-grid {
        grid-template-columns: repeat(2,minmax(0,1fr));
    }

    .nx-links-grid {
        grid-template-columns: 1fr;
    }
}


/* =========================================================
   RESPONSIVE — 800px
   ========================================================= */

@media (max-width: 800px) {

    .nexora-profile-page {
        padding: 22px 18px 55px;
    }

    .nx-profile-hero {
        padding: 26px;
    }

    .nx-fields-grid {
        grid-template-columns: 1fr;
    }

    .nx-field-full {
        grid-column: auto;
    }

    .nx-placement-grid {
        grid-template-columns: 1fr;
    }

    .nx-account-grid {
        grid-template-columns: 1fr;
    }

    .nx-staff-info-grid {
        grid-template-columns: 1fr;
    }

    .nx-save-bar {
        align-items: flex-start;

        flex-direction: column;
    }

    .nx-save-actions {
        width: 100%;
    }

    .nx-save-actions button {
        flex: 1;
    }
}


/* =========================================================
   RESPONSIVE — 620px
   ========================================================= */

@media (max-width: 620px) {

    .nexora-profile-page {
        padding: 15px 12px 45px;
    }

    .nx-profile-hero {
        min-height: auto;

        padding: 23px 20px;

        border-radius: 17px;
    }

    .nx-hero-left {
        width: 100%;

        align-items: flex-start;

        flex-direction: column;

        gap: 15px;
    }

    .nx-avatar {
        width: 76px;
        height: 76px;
        min-width: 76px;

        border-radius: 19px;

        font-size: 27px;
    }

    .nx-hero-content {
        width: 100%;
    }

    .nx-hero-content h1 {
        font-size: 24px;
    }

    .nx-hero-meta {
        align-items: flex-start;

        flex-direction: column;

        gap: 7px;
    }

    .nx-hero-actions {
        width: 100%;
    }

    .nx-edit-btn {
        width: 100%;
    }

    .nx-completion-card {
        align-items: flex-start;

        flex-direction: column;

        padding: 18px;
    }

    .nx-completion-main {
        width: 100%;
    }

    .nx-completion-status {
        width: 100%;

        justify-content: center;

        box-sizing: border-box;
    }

    .nx-card-header {
        padding: 18px;
    }

    .nx-card-title-wrap {
        align-items: flex-start;
    }

    .nx-section-badge {
        display: none;
    }

    .nx-fields-grid,
    .nx-placement-grid,
    .nx-account-grid,
    .nx-staff-info-grid,
    .nx-stats-grid {
        padding: 18px;
    }

    .nx-academic-highlight {
        margin-left: 18px;
        margin-right: 18px;

        grid-template-columns: 1fr 1fr;

        gap: 18px;
    }

    .academic-fields {
        padding-top: 18px !important;
    }

    .nx-professional-section {
        padding: 18px;
    }

    .nx-links-grid {
        padding: 0 18px 18px;
    }

    .nx-resume-section {
        padding: 0 18px 18px;
    }

    .nx-subheading {
        align-items: flex-start;

        flex-direction: column;
    }

    .nx-subheading > div:first-child {
        width: 100%;
    }

    .nx-small-btn,
    .nx-request-skill-btn {
        width: 100%;
    }

    .nx-skills {
        margin-top: 15px;
    }

    .nx-resume-card {
        align-items: flex-start;

        flex-direction: column;
    }

    .nx-resume-left {
        width: 100%;
    }

    .nx-resume-actions {
        width: 100%;
    }

    .nx-resume-view,
    .nx-resume-replace {
        flex: 1;
    }

    .nx-resume-upload-card {
        align-items: flex-start;

        flex-wrap: wrap;
    }

    .nx-upload-content {
        flex: 1;
    }

    .nx-upload-btn {
        width: 100%;
    }

    .nx-save-bar {
        padding: 15px;
    }

    .nx-modal-overlay {
        padding: 10px;
    }

    .nx-modal {
        max-height: calc(100vh - 20px);

        border-radius: 15px;
    }

    .nx-modal-header,
    .nx-modal-body {
        padding-left: 17px;
        padding-right: 17px;
    }

    .nx-modal-footer {
        padding-left: 17px;
        padding-right: 17px;
    }
}


/* =========================================================
   RESPONSIVE — 430px
   ========================================================= */

@media (max-width: 430px) {

    .nx-profile-hero {
        padding: 20px 17px;
    }

    .nx-profile-content {
        width: 100%;
    }

    .nx-completion-main {
        align-items: flex-start;
    }

    .nx-completion-title-row {
        align-items: flex-start;

        flex-direction: column;

        gap: 4px;
    }

    .nx-academic-highlight {
        grid-template-columns: 1fr;
    }

    .nx-academic-item {
        padding: 5px 0;
    }

    .nx-links-grid {
        grid-template-columns: 1fr;
    }

    .nx-stats-grid {
        grid-template-columns: 1fr;
    }

    .nx-staff-role-banner {
        align-items: flex-start;
    }

    .nx-save-actions {
        flex-direction: column;
    }

    .nx-save-actions button {
        width: 100%;
    }

    .nx-modal-footer {
        flex-direction: column;
    }

    .nx-modal-cancel,
    .nx-modal-primary {
        width: 100%;
    }
}
/* =========================================================
   RESUME PREVIEW / DOWNLOAD
   ========================================================= */

.nx-resume-download {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 6px;
    padding: 8px 11px;
    border: 1px solid #d8e3e9;
    border-radius: 8px;
    background: #fff;
    color: #315a71;
    font-family: inherit;
    font-size: 9px;
    font-weight: 800;
    cursor: pointer;
    transition: .2s ease;
}

.nx-resume-download:hover {
    background: #eef5f8;
}

.nx-resume-view:disabled,
.nx-resume-download:disabled {
    opacity: .6;
    cursor: not-allowed;
}

.nx-preview-modal {
    max-width: 980px;
    height: calc(100vh - 40px);
}

.nx-preview-title {
    max-width: 640px;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.nx-modal-body.nx-preview-body {
    padding: 0;
    display: flex;
    overflow: hidden;
    background: #eef2f5;
}

.nx-preview-frame {
    flex: 1;
    width: 100%;
    height: 100%;
    min-height: 60vh;
    border: 0;
    background: #fff;
}

.nx-preview-fallback {
    flex: 1;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 10px;
    padding: 30px;
    text-align: center;
    color: #687886;
}

.nx-preview-fallback i.fa-file-word-o {
    font-size: 46px;
    color: #315b73;
}

.nx-preview-fallback strong {
    color: #20394c;
    font-size: 14px;
}

.nx-preview-fallback span {
    font-size: 11px;
    max-width: 360px;
    line-height: 1.5;
}

@media (max-width: 620px) {
    .nx-preview-modal { height: calc(100vh - 20px); }
    .nx-resume-download { flex: 1; }
}
.nx-modal-backdrop {
    position: fixed;
    inset: 0;
    z-index: 9999;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 24px;
    background: rgba(17, 35, 50, .48);
    box-sizing: border-box;
}

.nx-skill-request-modal {
    
    max-height: calc(100vh - 48px);
    overflow: auto;
    border-radius: 18px;
    background: #ffffff;
    box-shadow: 0 25px 70px rgba(13,31,46,.28);
}

.nx-modal-header {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 18px;
    padding: 22px 24px 18px;
    border-bottom: 1px solid #edf1f4;
}

.nx-modal-eyebrow {
    display: block;
    margin-bottom: 5px;
    color: #ff6b5b;
    font-size: 9px;
    font-weight: 850;
    letter-spacing: 1px;
}

.nx-modal-header h3 {
    margin: 0;
    color: #17334b;
    font-size: 19px;
    font-weight: 800;
}

.nx-modal-header p {
    margin: 5px 0 0;
    color: #84919d;
    font-size: 11px;
}

.nx-modal-close {
    width: 32px;
    height: 32px;
    flex: 0 0 32px;
    border: 1px solid #e1e7ec;
    border-radius: 9px;
    background: #ffffff;
    color: #7d8b97;
    cursor: pointer;
}

.nx-modal-close:hover {
    border-color: #ff6b5b;
    color: #ff6b5b;
}

.nx-modal-body {
    padding: 22px 24px;
}

.nx-modal-field label,
.nx-modal-readonly-item span {
    display: block;
    margin-bottom: 7px;
    color: #637383;
    font-size: 10px;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: .55px;
}

.nx-modal-field .nx-input-wrap input {
    height: 44px;
}

.nx-modal-field small {
    display: block;
    margin-top: 6px;
    color: #8b98a4;
    font-size: 10px;
}

.nx-modal-readonly-grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 12px;
    margin-top: 18px;
}

.nx-modal-readonly-item {
    padding: 12px;
    border: 1px solid #e4eaef;
    border-radius: 10px;
    background: #f8fafb;
}

.nx-modal-readonly-item strong {
    display: block;
    color: #30485a;
    font-size: 12px;
}

.nx-pending-text {
    color: #a87915 !important;
}

.nx-modal-alert {
    display: flex;
    align-items: flex-start;
    gap: 8px;
    margin-bottom: 15px;
    padding: 10px 12px;
    border-radius: 9px;
    font-size: 11px;
    line-height: 1.4;
}

.nx-modal-alert-error {
    background: #fff1ef;
    color: #c95045;
}

.nx-modal-alert-success {
    background: #edf9f4;
    color: #16815e;
}

.nx-modal-footer {
    display: flex;
    justify-content: flex-end;
    gap: 10px;
    padding: 16px 24px;
    border-top: 1px solid #edf1f4;
    background: #fbfcfd;
}

.nx-submit-skill-btn {
    min-width: 145px;
}

@media (max-width: 600px) {
    .nx-skill-heading-row {
        align-items: flex-start;
        flex-direction: column;
    }

    .nx-request-skill-btn {
        width: 100%;
        justify-content: center;
    }

    .nx-skill-request-item {
        align-items: flex-start;
        flex-direction: column;
    }

    .nx-modal-readonly-grid {
        grid-template-columns: 1fr;
    }

    .nx-modal-footer {
        flex-direction: column;
    }

    .nx-modal-footer button {
        width: 100%;
    }
}


/* ============================================================
   ADD EXISTING SKILLS
   ============================================================ */

.nx-skill-actions {
    display: inline-flex;
    align-items: center;
    justify-content: flex-end;
    gap: 8px;
    flex-wrap: wrap;
}

.nx-add-skill-btn {
    display: inline-flex;
    align-items: center;
    gap: 7px;
    padding: 9px 13px;
    border: 1px solid #dce4eb;
    border-radius: 9px;
    background: #ffffff;
    color: #17334b;
    font-size: 11px;
    font-weight: 750;
    cursor: pointer;
    transition: .2s ease;
}

.nx-add-skill-btn i {
    color: #159c78;
}

.nx-add-skill-btn:hover {
    border-color: #159c78;
    color: #159c78;
    transform: translateY(-1px);
}

.nx-add-skill-modal {
    
}

.nx-skill-catalog-search {
    position: relative;
    margin-bottom: 12px;
}

.nx-skill-catalog-search i {
    position: absolute;
    left: 13px;
    top: 50%;
    transform: translateY(-50%);
    color: #9aa8b4;
    font-size: 12px;
}

.nx-skill-catalog-search input {
    width: 100%;
    height: 42px;
    padding: 0 13px 0 35px;
    border: 1px solid #dce4eb;
    border-radius: 9px;
    background: #f9fbfc;
    color: #30485a;
    box-sizing: border-box;
    outline: none;
}

.nx-skill-catalog-search input:focus {
    border-color: #159c78;
    background: #ffffff;
}

.nx-skill-catalog-list {
    max-height: 310px;
    overflow-y: auto;
    border: 1px solid #e0e7ed;
    border-radius: 11px;
    background: #ffffff;
}

.nx-catalog-skill-row {
    position: relative;
    display: flex;
    align-items: center;
    gap: 11px;
    min-height: 54px;
    padding: 8px 13px;
    margin: 0;
    border-bottom: 1px solid #edf1f4;
    cursor: pointer;
    transition: .15s ease;
}

.nx-catalog-skill-row:last-child {
    border-bottom: 0;
}

.nx-catalog-skill-row:hover {
    background: #f8fbfa;
}

.nx-catalog-skill-row input {
    position: absolute;
    opacity: 0;
    pointer-events: none;
}

.nx-catalog-check {
    width: 20px;
    height: 20px;
    flex: 0 0 20px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border: 1px solid #d3dfe6;
    border-radius: 6px;
    background: #ffffff;
    color: #ffffff;
    font-size: 10px;
}

.nx-catalog-skill-selected .nx-catalog-check {
    border-color: #159c78;
    background: #159c78;
}

.nx-catalog-skill-info {
    min-width: 0;
    flex: 1;
}

.nx-catalog-skill-info strong {
    display: block;
    color: #30485a;
    font-size: 12px;
}

.nx-catalog-skill-info small {
    display: block;
    margin-top: 2px;
    color: #8a98a5;
    font-size: 9px;
}

.nx-catalog-skill-disabled {
    cursor: default;
    background: #fafcfd;
    opacity: .72;
}

.nx-catalog-existing {
    flex: 0 0 auto;
    padding: 4px 8px;
    border-radius: 15px;
    background: #edf8f4;
    color: #13865f;
    font-size: 8px;
    font-weight: 800;
    text-transform: uppercase;
}

.nx-catalog-empty {
    min-height: 120px;
    justify-content: center;
    border: 1px solid #e0e7ed;
    border-radius: 11px;
}

.nx-selected-count {
    margin-right: auto;
    color: #81909c;
    font-size: 10px;
    font-weight: 700;
}

.nx-modal-footer-actions {
    display: flex;
    align-items: center;
    gap: 10px;
}

@media (max-width: 600px) {
    .nx-skill-actions {
        width: 100%;
        justify-content: stretch;
    }

    .nx-skill-actions button {
        flex: 1;
        justify-content: center;
    }

    .nx-modal-footer {
        align-items: stretch;
        flex-direction: column;
    }

    .nx-selected-count {
        margin-right: 0;
    }

    .nx-modal-footer-actions {
        width: 100%;
    }

    .nx-modal-footer-actions button {
        flex: 1;
    }
}
/* ============================================================
   REMOVE SKILL BUTTON
   ============================================================ */

.nx-skill-chip {
    position: relative;
    padding-right: 9px;
}

.nx-remove-skill-btn {
    width: 22px;
    height: 22px;
    flex: 0 0 22px;

    display: inline-flex;
    align-items: center;
    justify-content: center;

    margin-left: 2px;

    border: 0;
    border-radius: 50%;

    background: transparent;
    color: #9aa8b4;

    font-size: 9px;

    cursor: pointer;

    transition:
        background .18s ease,
        color .18s ease,
        transform .18s ease;
}

.nx-remove-skill-btn:hover {
    background: #fff0ed;
    color: #e45c4e;
    transform: scale(1.08);
}

.nx-remove-skill-btn:focus {
    outline: none;
    box-shadow: 0 0 0 2px rgba(255,107,91,.12);
}

.nx-remove-skill-btn:active {
    transform: scale(.94);
}
.nx-secondary-btn,
.nx-save-btn {

    min-width:
        120px;

    height:
        42px;

    padding:
        0 17px;

    border-radius:
        10px;

    font-size:
        12px;

    font-weight:
        750;

    cursor:
        pointer;

    transition:
        all .18s ease;
}


.nx-secondary-btn {

    border:
        1px solid #d8dfe6;

    background:
        #ffffff;

    color:
        #526372;
}


.nx-secondary-btn:hover {

    background:
        #f5f7f9;
}
/* =========================================================
   FIXES / ADDITIONS  (append to the end of your CSS)
   ========================================================= */

/* Alerts become toasts so they are visible wherever the user is scrolled */
.nx-alert {
    position: fixed;
    top: 76px;
    right: 24px;
    z-index: 100000;
    width: auto;
    max-width: 420px;
    margin-top: 0;
    box-shadow: 0 12px 30px rgba(23,43,63,.18);
    animation: nxToastIn .2s ease;
}

@keyframes nxToastIn {
    from { opacity: 0; transform: translateY(-8px); }
    to   { opacity: 1; transform: none; }
}

.nx-alert-close {
    margin-left: auto;
    border: 0;
    background: transparent;
    color: inherit;
    opacity: .6;
    cursor: pointer;
}

.nx-alert-close:hover { opacity: 1; }

/* Select boxes (gender / language) */
.nx-input-wrap select {
    width: 100%;
    box-sizing: border-box;
    border: 1px solid #e0e6eb;
    border-radius: 10px;
    background: #f9fafb;
    color: #24384a;
    padding: 11px 13px 11px 36px;
    font-family: inherit;
    font-size: 12px;
    outline: none;
    transition: .2s ease;
}

.nx-input-wrap select:focus {
    border-color: #ff9185;
    background: #fff;
    box-shadow: 0 0 0 3px rgba(255,107,91,.08);
}

.nx-input-wrap select:disabled {
    opacity: 1;
    cursor: default;
    color: #3b5264;
    background: #f8fafb;
    -webkit-appearance: none;
    appearance: none;
}

/* Skill remove (x) button inside the chip */
.nx-skill-remove {
    margin-left: 8px;
    padding: 0;
    width: 16px;
    height: 16px;
    border: 0;
    border-radius: 50%;
    background: transparent;
    color: #7a93a3;
    font-size: 9px;
    cursor: pointer;
}

.nx-skill-remove:hover { background: #ff6b5b; color: #fff; }

/* Save bar always reachable + inline error */
.nx-save-bar {
    position: sticky;
    bottom: 14px;
    z-index: 50;
}

.nx-save-bar .nx-save-error {
    color: #c0392b;
    font-weight: 700;
}

.nx-save-btn:disabled,
.nx-upload-btn:disabled,
.nx-resume-replace:disabled {
    opacity: .6;
    cursor: not-allowed;
}
/* =========================================================
   RESUME PREVIEW / DOWNLOAD
   ========================================================= */

.nx-resume-download {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 6px;
    padding: 8px 11px;
    border: 1px solid #d8e3e9;
    border-radius: 8px;
    background: #fff;
    color: #315a71;
    font-family: inherit;
    font-size: 9px;
    font-weight: 800;
    cursor: pointer;
    transition: .2s ease;
}

.nx-resume-download:hover {
    background: #eef5f8;
}

.nx-resume-view:disabled,
.nx-resume-download:disabled {
    opacity: .6;
    cursor: not-allowed;
}

.nx-preview-modal {
    max-width: 980px;
    height: calc(100vh - 40px);
}

.nx-preview-title {
    max-width: 640px;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.nx-modal-body.nx-preview-body {
    padding: 0;
    display: flex;
    overflow: hidden;
    background: #eef2f5;
}

.nx-preview-frame {
    flex: 1;
    width: 100%;
    height: 100%;
    min-height: 60vh;
    border: 0;
    background: #fff;
}

.nx-preview-fallback {
    flex: 1;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 10px;
    padding: 30px;
    text-align: center;
    color: #687886;
}

.nx-preview-fallback i.fa-file-word-o {
    font-size: 46px;
    color: #315b73;
}

.nx-preview-fallback strong {
    color: #20394c;
    font-size: 14px;
}

.nx-preview-fallback span {
    font-size: 11px;
    max-width: 360px;
    line-height: 1.5;
}

@media (max-width: 620px) {
    .nx-preview-modal { height: calc(100vh - 20px); }
    .nx-resume-download { flex: 1; }
}

sp_widget.script:
(function() {

    /* =========================================================
       NEXORA — MY PROFILE  (SERVER SCRIPT)
       Actions: load | update_profile | upload_resume | get_resume |
                add_skills | remove_skill | request_skill
       The profile is ALWAYS reloaded at the end.
       ========================================================= */

    data.profile = null;
    data.success = false;
    data.error = '';
    data.message = '';
    data.action = (input && input.action) ? String(input.action) : 'load';


    /* ---------- CONSTANTS ---------- */

    var STUDENT_TABLE       = 'x_snc_college_pl_0_student';
    var APPLICATION_TABLE   = 'x_snc_college_pl_0_application';
    var DRIVE_TABLE         = 'x_snc_college_pl_0_placement_drive';
    var INTERVIEW_TABLE     = 'x_snc_college_pl_0_interview';
    var SKILL_CATALOG_TABLE = 'x_snc_college_pl_0_skills_catalog';
    var SKILL_REQUEST_TABLE = 'x_snc_college_pl_0_skill_request';
    var OFFER_TABLE         = 'x_snc_college_pl_0_offer_letter';
    var COMPANY_TABLE       = 'x_snc_college_pl_0_company';   // <-- change if your company table name differs

    var MAX_RESUME_BYTES = 3 * 1024 * 1024;   // keep in sync with the client (3 MB)

    var RESUME_TYPES = {
        pdf:  'application/pdf',
        doc:  'application/msword',
        docx: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document'
    };

    var EMAIL_REGEX = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

    var studentGR = null;


    /* ---------- SMALL HELPERS ---------- */

    function fail(msg) {
        data.success = false;
        data.error = msg;
        data.message = msg;
    }

    function succeed(msg, flag) {
        data.success = true;
        data.error = '';
        data.message = msg;
        if (flag) {
            data[flag] = true;
        }
    }

    function safeValue(gr, field) {
        return gr.isValidField(field) ? (gr.getValue(field) || '') : '';
    }

    function safeDisplay(gr, field) {
        return gr.isValidField(field) ? (gr.getDisplayValue(field) || '') : '';
    }

    function setIfValid(gr, field, value) {
        if (gr.isValidField(field)) {
            gr.setValue(field, value);
            return true;
        }
        return false;
    }

    function digitsOnly(value) {
        return String(value || '').replace(/[^0-9]/g, '');
    }

    function getExtension(fileName) {
        var parts = String(fileName || '').split('.');
        return parts.length > 1 ? String(parts[parts.length - 1]).toLowerCase() : '';
    }

    function getCount(tableName, encodedQuery) {
        var ga = new GlideAggregate(tableName);
        if (!ga.isValid()) {
            return 0;
        }
        if (encodedQuery) {
            ga.addEncodedQuery(encodedQuery);
        }
        ga.addAggregate('COUNT');
        ga.query();
        return ga.next() ? (parseInt(ga.getAggregate('COUNT'), 10) || 0) : 0;
    }

    function getChoices(tableName, fieldName) {
        var list = [];
        try {
            var gr = new GlideRecord('sys_choice');
            gr.addQuery('name', tableName);
            gr.addQuery('element', fieldName);
            gr.addQuery('inactive', false);
            gr.orderBy('sequence');
            gr.query();
            while (gr.next()) {
                list.push({
                    value: gr.getValue('value'),
                    label: gr.getValue('label')
                });
            }
        } catch (e) {
            gs.warn('NEXORA getChoices failed for ' + fieldName + ': ' + e.message);
        }
        return list;
    }

    function hasAnyRole(roleList) {
        for (var r = 0; r < roleList.length; r++) {
            if (gs.hasRole(roleList[r])) {
                return true;
            }
        }
        return false;
    }


    /* ---------- CURRENT USER ---------- */

    var userId = gs.getUserID();

    if (!userId) {
        fail('Unable to identify the logged-in user.');
        return;
    }

    var userGR = new GlideRecord('sys_user');

    if (!userGR.get(userId)) {
        fail('Unable to load the logged-in user information.');
        return;
    }

    var userName       = userGR.getDisplayValue('name') || 'User';
    var userEmail      = userGR.getValue('email') || '';
    var username       = userGR.getValue('user_name') || '';
    var userActive     = userGR.getValue('active') === 'true';
    var userTitle      = safeValue(userGR, 'title');
    var userDepartment = safeDisplay(userGR, 'department');
    var userMobile     = safeValue(userGR, 'mobile_phone');
    var userCreatedOn  = safeDisplay(userGR, 'sys_created_on');


    /* ---------- ROLES ---------- */

    var isPlacementAdmin   = hasAnyRole(['x_snc_college_pl_0.placement_admin', 'placement_admin', 'admin']);
    var isPlacementOfficer = hasAnyRole(['x_snc_college_pl_0.placement_officer', 'placement_officer']);
    var isInterviewer      = hasAnyRole(['x_snc_college_pl_0.interviewer', 'interviewer']);
    var isStudentRole      = hasAnyRole(['x_snc_college_pl_0.student_user', 'student_user']);

    var role = 'User';

    if (isPlacementAdmin)        { role = 'Placement Admin'; }
    else if (isPlacementOfficer) { role = 'Placement Officer'; }
    else if (isInterviewer)      { role = 'Interviewer'; }
    else if (isStudentRole)      { role = 'Student'; }

    var isStudent = (role === 'Student');

    data.isStudent          = isStudent;
    data.isPlacementOfficer = (role === 'Placement Officer');
    data.isPlacementAdmin   = (role === 'Placement Admin');
    data.isInterviewer      = (role === 'Interviewer');
    data.role               = role;
    data.roleLabel          = role;

    data.statistics = {
        companies: 0, students: 0, drives: 0, applications: 0,
        interviews: 0, selections: 0, offers: 0, pending: 0
    };


    /* =========================================================
       MAIN FLOW
       ========================================================= */

    if (isStudent) {

        studentGR = new GlideRecord(STUDENT_TABLE);

        if (!studentGR.isValid()) {
            fail('Student table could not be loaded.');
            return;
        }

        studentGR.addQuery('user', userId);
        studentGR.setLimit(1);
        studentGR.query();

        if (!studentGR.next()) {
            fail('Student profile not found for the logged-in user.');
            return;
        }

        runStudentAction();
        loadStudentProfile();     // ALWAYS reload so the page is never blank
        return;
    }

    if (isPlacementAdmin || isPlacementOfficer || isInterviewer) {
        loadStaffProfile();
        return;
    }

    loadUnknownProfile();
    return;


    /* =========================================================
       STUDENT ACTION ROUTER
       ========================================================= */

    function runStudentAction() {
        switch (data.action) {
            case 'update_profile': actionUpdateProfile(); break;
            case 'upload_resume':  actionUploadResume();  break;
            case 'get_resume':     actionGetResume();     break;
            case 'add_skills':     actionAddSkills();     break;
            case 'remove_skill':   actionRemoveSkill();   break;
            case 'request_skill':  actionRequestSkill();  break;
            default: break;   // plain load
        }
    }


    /* =========================================================
       RESUME LOOKUP  (reads sys_attachment directly)
       Returns { id, name }. id is '' when no attachment exists.
       ========================================================= */

    function findResume() {

        var result = { id: '', name: '' };

        var fieldName = safeValue(studentGR, 'resume');

        var att = new GlideRecord('sys_attachment');
        att.addQuery('table_name', STUDENT_TABLE);
        att.addQuery('table_sys_id', studentGR.getUniqueValue());
        att.orderByDesc('sys_created_on');
        att.query();

        var newest = null;
        var matching = null;

        while (att.next()) {

            var fn = att.getValue('file_name') || '';

            if (!RESUME_TYPES[getExtension(fn)]) {
                continue;
            }

            var entry = { id: att.getUniqueValue(), name: fn };

            if (!newest) {
                newest = entry;                       // ordered newest first
            }

            if (fieldName && fn === fieldName && !matching) {
                matching = entry;
            }
        }

        var chosen = matching || newest;

        if (chosen) {
            result.id = chosen.id;
            result.name = chosen.name;
        } else if (fieldName) {
            // field is filled but the attachment is missing: still show the name
            result.name = fieldName;
            gs.warn('NEXORA: resume field is set (' + fieldName + ') but no attachment was found for student ' + studentGR.getUniqueValue());
        }

        return result;
    }


    /* =========================================================
       ACTION: UPLOAD RESUME
       ========================================================= */

    function actionUploadResume() {

        if (!input || !input.resumeFile) {
            return fail('No resume file was received.');
        }

        if (!studentGR.canWrite()) {
            return fail('You do not have permission to upload a resume. (Check the write ACL on the student table.)');
        }

        var file = input.resumeFile;
        var fileName = String(file.fileName || '').trim();
        var base64 = String(file.base64 || '').trim();

        if (!fileName || !base64) {
            return fail('No valid resume file was received.');
        }

        // strip a possible "data:...;base64," prefix
        var commaPos = base64.indexOf(',');
        if (base64.indexOf('data:') === 0 && commaPos !== -1) {
            base64 = base64.substring(commaPos + 1);
        }

        var ext = getExtension(fileName);

        if (!RESUME_TYPES[ext]) {
            return fail('Only PDF, DOC and DOCX files are allowed.');
        }

        if ((base64.length * 0.75) > MAX_RESUME_BYTES) {
            return fail('Resume size must be less than 3 MB.');
        }

        try {

            var gsa = new GlideSysAttachment();

            // 1) collect the old resume attachments (same name as current resume or as the new file)
            var currentResume = safeValue(studentGR, 'resume');
            var oldIds = [];

            var existing = new GlideRecord('sys_attachment');
            existing.addQuery('table_name', STUDENT_TABLE);
            existing.addQuery('table_sys_id', studentGR.getUniqueValue());
            existing.query();

            while (existing.next()) {
                var existingName = existing.getValue('file_name') || '';
                if (existingName === fileName || (currentResume && existingName === currentResume)) {
                    oldIds.push(existing.getUniqueValue());
                }
            }

            // 2) write the new file first (so the old one is never lost on failure)
            var newAttachmentId = gsa.writeBase64(studentGR, fileName, RESUME_TYPES[ext], base64);

            if (!newAttachmentId) {
                return fail('Resume could not be uploaded.');
            }

            newAttachmentId = String(newAttachmentId);

            // 3) delete the old copies
            for (var i = 0; i < oldIds.length; i++) {
                if (oldIds[i] !== newAttachmentId) {
                    gsa.deleteAttachment(oldIds[i]);
                }
            }

            // 4) store the file name on the student record (if the field exists)
            if (studentGR.isValidField('resume')) {
                studentGR.setValue('resume', fileName);
                if (!studentGR.update()) {
                    gs.warn('NEXORA: resume attached but the resume field could not be updated for user ' + userId);
                }
            }

            gs.info('NEXORA: resume uploaded. attachment=' + newAttachmentId + ' file=' + fileName + ' user=' + userId);

            // returned directly so the page can show the file immediately
            data.resumeName = fileName;
            data.resumeAttachmentId = newAttachmentId;

            succeed('Resume uploaded successfully.', 'resumeUploaded');

        } catch (e) {
            gs.error('NEXORA Resume Upload Error: ' + e.message);
            fail('Resume upload failed. Please try again.');
        }
    }


    /* =========================================================
       ACTION: GET RESUME (for preview / download)
       Only the logged-in student's own resume is ever returned.
       ========================================================= */

    function actionGetResume() {

        var found = findResume();

        if (!found.id) {
            return fail('No resume file was found on your profile. Please upload your resume again.');
        }

        try {

            var attGR = new GlideRecord('sys_attachment');

            if (!attGR.get(found.id)) {
                return fail('The resume file could not be opened.');
            }

            var base64 = new GlideSysAttachment().getContentBase64(attGR);

            if (!base64) {
                return fail('The resume file is empty or could not be read.');
            }

            var ext = getExtension(found.name);

            data.resumePreview = {
                fileName: found.name,
                contentType: RESUME_TYPES[ext] || 'application/octet-stream',
                base64: String(base64)
            };

            succeed('', 'resumeLoaded');

        } catch (e) {
            gs.error('NEXORA Resume Read Error: ' + e.message);
            fail('Unable to open the resume. Please try again.');
        }
    }


    /* =========================================================
       ACTION: UPDATE PROFILE
       ========================================================= */

    function actionUpdateProfile() {

        var p = null;

        if (input && input.profileUpdate) {
            p = input.profileUpdate;
        } else if (input && input.profile) {
            p = input.profile;
        }

        if (!p) {
            return fail('No profile data was received from the page.');
        }

        if (!studentGR.canWrite()) {
            return fail('You do not have permission to edit this profile. (Check the write ACL on the student table.)');
        }

        var fullName = String(p.fullName || '').trim();
        if (fullName.length < 2) {
            return fail('Please enter a valid student name.');
        }

        var email = String(p.email || '').trim();
        if (!EMAIL_REGEX.test(email)) {
            return fail('Please enter a valid email address.');
        }

        var mobile = String(p.mobile || '').trim();
        var mobileDigits = digitsOnly(mobile);
        if (mobileDigits.length < 10 || mobileDigits.length > 15) {
            return fail('Please enter a valid mobile number (10 to 15 digits).');
        }

        var fatherMobile = String(p.fatherMobile || '').trim();
        if (fatherMobile) {
            var fmDigits = digitsOnly(fatherMobile);
            if (fmDigits.length < 10 || fmDigits.length > 15) {
                return fail('Please enter a valid parent / guardian mobile number.');
            }
        }

        var alternateEmail = String(p.alternateEmail || '').trim();
        if (alternateEmail && !EMAIL_REGEX.test(alternateEmail)) {
            return fail('Please enter a valid alternate email address.');
        }

        var git = String(p.git || '').trim();
        if (git && git.toLowerCase().indexOf('github.com') === -1) {
            return fail('Please enter a valid GitHub URL.');
        }

        var linkedin = String(p.linkedin || '').trim();
        if (linkedin && linkedin.toLowerCase().indexOf('linkedin.com') === -1) {
            return fail('Please enter a valid LinkedIn URL.');
        }

        setIfValid(studentGR, 'student_name', fullName);
        setIfValid(studentGR, 'email', email);
        setIfValid(studentGR, 'mobile_number', mobile);
        setIfValid(studentGR, 'father_name', String(p.fatherName || '').trim());
        setIfValid(studentGR, 'father_mobile_number', fatherMobile);
        setIfValid(studentGR, 'address', String(p.address || '').trim());
        setIfValid(studentGR, 'student_email', alternateEmail);
        setIfValid(studentGR, 'git', git);
        setIfValid(studentGR, 'linkedin', linkedin);

        var gender = String(p.gender || '').trim();
        if (gender) {
            setIfValid(studentGR, 'gender', gender);
        }

        var language = String(p.language || '').trim();
        if (language) {
            setIfValid(studentGR, 'language', language);
        }

        var updatedId = studentGR.update();

        if (!updatedId) {
            var why = '';
            try { why = studentGR.getLastErrorMessage() || ''; } catch (e) { why = ''; }
            gs.error('NEXORA profile update failed for user ' + userId + ' : ' + why);
            return fail('Your profile could not be saved. ' + (why ? why : 'Please check the write ACL / business rules on the student table.'));
        }

        succeed('Your profile has been updated successfully.');
    }


    /* =========================================================
       ACTION: ADD SKILLS
       ========================================================= */

    function actionAddSkills() {

        var ids = input ? input.selectedSkillIds : null;

        if (typeof ids === 'string') {
            ids = ids.split(',');
        }

        if (!ids || !ids.length) {
            return fail('Please select at least one skill.');
        }

        var existingValue = studentGR.getValue('skills') || '';
        var existingParts = existingValue ? existingValue.split(',') : [];

        var seen = {};
        var merged = [];

        for (var e = 0; e < existingParts.length; e++) {
            var existingId = String(existingParts[e] || '').trim();
            if (existingId && !seen[existingId]) {
                seen[existingId] = true;
                merged.push(existingId);
            }
        }

        var addedNames = [];

        for (var i = 0; i < ids.length; i++) {

            var skillId = String(ids[i] || '').trim();

            if (!skillId || seen[skillId]) {
                continue;
            }

            var skillGR = new GlideRecord(SKILL_CATALOG_TABLE);

            if (skillGR.get(skillId)) {
                var active = skillGR.getValue('active');
                if (active === 'true' || active === '1') {
                    seen[skillId] = true;
                    merged.push(skillId);
                    addedNames.push(skillGR.getValue('skill_name') || skillGR.getDisplayValue());
                }
            }
        }

        if (!addedNames.length) {
            return fail('The selected skills are already in your profile.');
        }

        studentGR.setValue('skills', merged.join(','));

        if (!studentGR.update()) {
            return fail('Unable to add the selected skills. Please try again.');
        }

        succeed(
            addedNames.join(', ') + (addedNames.length === 1 ? ' was added to your skills.' : ' were added to your skills.'),
            'skillsAdded'
        );
    }


    /* =========================================================
       ACTION: REMOVE SKILL
       ========================================================= */

    function actionRemoveSkill() {

        var removeId = String((input && input.skillId) || '').trim();

        if (!removeId) {
            return fail('Invalid skill selected.');
        }

        var current = studentGR.getValue('skills') || '';
        var parts = current ? current.split(',') : [];
        var remaining = [];
        var found = false;

        for (var i = 0; i < parts.length; i++) {
            var id = String(parts[i] || '').trim();
            if (!id) { continue; }
            if (id === removeId) { found = true; continue; }
            remaining.push(id);
        }

        if (!found) {
            return fail('This skill is not currently mapped to your profile.');
        }

        var removedName = 'Skill';
        var nameGR = new GlideRecord(SKILL_CATALOG_TABLE);
        if (nameGR.get(removeId)) {
            removedName = nameGR.getValue('skill_name') || nameGR.getDisplayValue();
        }

        studentGR.setValue('skills', remaining.join(','));

        if (!studentGR.update()) {
            return fail('Unable to remove the skill. Please try again.');
        }

        data.removedSkillId = removeId;
        succeed(removedName + ' was removed from your profile.', 'skillRemoved');
    }


    /* =========================================================
       ACTION: REQUEST A NEW SKILL
       ========================================================= */

    function actionRequestSkill() {

        var req = input ? input.skillRequest : null;
        var term = String((req && req.requestedTerm) || '').trim();
        var reason = String((req && req.reason) || '').trim();

        if (!term) {
            return fail('Please enter the skill you want to request.');
        }

        if (term.length > 100) {
            return fail('Skill name cannot exceed 100 characters.');
        }

        var reqGR = new GlideRecord(SKILL_REQUEST_TABLE);

        if (!reqGR.isValid()) {
            return fail('Skill Request table could not be loaded.');
        }

        reqGR.addQuery('requested_by', studentGR.getUniqueValue());
        reqGR.addQuery('requested_term', term);
        reqGR.addQuery('status', 'pending');
        reqGR.setLimit(1);
        reqGR.query();

        if (reqGR.next()) {
            return fail('You already have a pending request for this skill.');
        }

        reqGR.initialize();
        reqGR.setValue('requested_term', term);
        reqGR.setValue('requested_by', studentGR.getUniqueValue());
        reqGR.setValue('status', 'pending');

        if (reason) {
            if (!setIfValid(reqGR, 'reason', reason)) {
                setIfValid(reqGR, 'description', reason);
            }
        }

        var requestId = reqGR.insert();

        if (!requestId) {
            return fail('Unable to create the skill request. Please try again.');
        }

        data.skillRequestId = requestId;
        succeed('Skill request submitted successfully. It is now pending TPO approval.', 'skillRequestCreated');
    }


    /* =========================================================
       LOAD STUDENT PROFILE
       ========================================================= */

    function loadStudentProfile() {

        // reload the record so we always show what is really saved
        var sid = studentGR.getUniqueValue();
        studentGR = new GlideRecord(STUDENT_TABLE);
        studentGR.get(sid);

        var fullName        = safeValue(studentGR, 'student_name') || userName;
        var studentNumber   = safeValue(studentGR, 'number');
        var registerNumber  = safeValue(studentGR, 'register_number');
        var email           = safeValue(studentGR, 'email') || userEmail;
        var mobile          = safeValue(studentGR, 'mobile_number');
        var gender          = safeValue(studentGR, 'gender');          // RAW value
        var fatherName      = safeValue(studentGR, 'father_name');
        var fatherMobile    = safeValue(studentGR, 'father_mobile_number');
        var address         = safeValue(studentGR, 'address');
        var language        = safeValue(studentGR, 'language');        // RAW value
        var alternateEmail  = safeValue(studentGR, 'student_email');
        var collegeName     = safeValue(studentGR, 'college_name');
        var currentYear     = safeDisplay(studentGR, 'current_year');
        var branch          = safeDisplay(studentGR, 'branch');
        var cgpa            = safeValue(studentGR, 'cgpa');
        var backlogs        = safeValue(studentGR, 'backlogs');
        var passingYear     = safeValue(studentGR, 'passing_year');
        var git             = safeValue(studentGR, 'git');
        var linkedin        = safeValue(studentGR, 'linkedin');
        var eligibleRaw     = safeValue(studentGR, 'eligible');
        var placementStatus = safeDisplay(studentGR, 'placement_status');
        var createdOn       = safeDisplay(studentGR, 'sys_created_on');

        if (backlogs === '') {
            backlogs = '0';
        }

        /* ----- skills ----- */

        var skillIds = safeValue(studentGR, 'skills');
        var skillList = [];

        if (skillIds) {
            var sGR = new GlideRecord(SKILL_CATALOG_TABLE);
            if (sGR.isValid()) {
                sGR.addQuery('sys_id', 'IN', skillIds);
                sGR.orderBy('skill_name');
                sGR.query();
                while (sGR.next()) {
                    skillList.push({
                        sys_id: sGR.getUniqueValue(),
                        name: sGR.getValue('skill_name') || sGR.getDisplayValue(),
                        category: sGR.getDisplayValue('category') || ''
                    });
                }
            }
        }

        var skillNames = [];
        for (var k = 0; k < skillList.length; k++) {
            skillNames.push(skillList[k].name);
        }
        var skills = skillNames.join(', ');

        var skillCatalog = [];
        var cGR = new GlideRecord(SKILL_CATALOG_TABLE);
        if (cGR.isValid()) {
            cGR.addQuery('active', true);
            cGR.orderBy('skill_name');
            cGR.query();
            while (cGR.next()) {
                skillCatalog.push({
                    sys_id: cGR.getUniqueValue(),
                    name: cGR.getValue('skill_name') || cGR.getDisplayValue(),
                    category: cGR.getDisplayValue('category') || ''
                });
            }
        }

        /* ----- resume ----- */

        var resumeInfo = findResume();

        /* ----- eligibility (adapt this rule to your business logic) ----- */

        var eligLower = String(eligibleRaw).toLowerCase();

        var isEligible = (eligibleRaw === 'true' || eligibleRaw === '1' ||
                          eligLower === 'yes' || eligLower === 'eligible');

        var isNotEligible = (eligibleRaw === 'false' || eligibleRaw === '0' ||
                             eligLower === 'no' || eligLower === 'not eligible');

        var eligibility = isEligible ? 'Eligible' : (isNotEligible ? 'Not Eligible' : (eligibleRaw || 'Not Available'));

        var eligibleDrives = 0;
        if (isEligible) {
            var driveCheck = new GlideRecord(DRIVE_TABLE);
            eligibleDrives = (driveCheck.isValid() && driveCheck.isValidField('active'))
                ? getCount(DRIVE_TABLE, 'active=true')
                : getCount(DRIVE_TABLE);
        }

        /* ----- completion ----- */

        var completionFields = [
            fullName, registerNumber, email, mobile, gender, fatherName, fatherMobile,
            address, language, alternateEmail, collegeName, currentYear, branch, cgpa,
            backlogs, passingYear, skills, git, linkedin, resumeInfo.name
        ];

        var filled = 0;
        for (var i = 0; i < completionFields.length; i++) {
            var val = completionFields[i];
            if (val !== null && typeof val !== 'undefined' && String(val).trim() !== '') {
                filled++;
            }
        }

        var completion = Math.round((filled / completionFields.length) * 100);

        /* ----- final object ----- */

        data.profile = {

            role: 'Student',
            roleLabel: 'Student',
            isStudent: true,
            isOfficer: false,
            isAdmin: false,
            isInterviewer: false,

            sys_id: studentGR.getUniqueValue(),
            number: studentNumber,
            studentId: studentNumber,

            fullName: fullName,
            email: email,
            mobile: mobile,
            gender: gender,
            genderChoices: getChoices(STUDENT_TABLE, 'gender'),
            fatherName: fatherName,
            fatherMobile: fatherMobile,
            address: address,
            language: language,
            languageChoices: getChoices(STUDENT_TABLE, 'language'),
            alternateEmail: alternateEmail,

            registerNumber: registerNumber,
            collegeName: collegeName,
            college: collegeName,
            currentYear: currentYear,
            branch: branch,
            cgpa: cgpa,
            backlogs: backlogs,
            passingYear: passingYear,
            graduationYear: passingYear,

            skills: skills,
            skillList: skillList,
            skillCatalog: skillCatalog,

            resume: resumeInfo.name,
            resumeAttachmentId: resumeInfo.id,
            resumeUrl: resumeInfo.id ? ('/sys_attachment.do?sys_id=' + resumeInfo.id) : '',
            git: git,
            linkedin: linkedin,

            eligible: eligibleRaw,
            eligibility: eligibility,
            eligibleDrives: eligibleDrives,
            placementStatus: placementStatus,

            username: username,
            status: userActive ? 'Active Student' : 'Inactive',
            createdOn: createdOn,
            completion: completion,
            profileCompletion: completion,

            preferredRole: '',
            title: '',
            department: '',
            company: '',
            location: '',
            manager: '',
            roleDescription: '',

            statistics: data.statistics
        };
    }


    /* =========================================================
       STAFF STATISTICS
       ========================================================= */

    function loadStaffStatistics() {

        var s = data.statistics;

        s.companies    = getCount(COMPANY_TABLE);
        s.students     = getCount(STUDENT_TABLE);
        s.drives       = getCount(DRIVE_TABLE);
        s.applications = getCount(APPLICATION_TABLE);
        s.selections   = getCount(APPLICATION_TABLE, 'status=Selected');
        s.offers       = getCount(OFFER_TABLE);

        var iGR = new GlideRecord(INTERVIEW_TABLE);

        if (iGR.isValid()) {

            iGR.query();

            while (iGR.next()) {

                s.interviews++;

                var status = String(iGR.getDisplayValue('status') || '').toLowerCase();
                var result = String(iGR.getDisplayValue('result') || '').trim();
                var feedback = String(iGR.getValue('feedback') || '').trim();

                if (!(status === 'completed' && (result || feedback))) {
                    s.pending++;
                }
            }
        }
    }


    /* =========================================================
       STAFF PROFILE
       ========================================================= */

    function loadStaffProfile() {

        loadStaffStatistics();

        var roleDescription = '';

        if (isPlacementAdmin) {
            roleDescription = 'Manage placement operations, students, drives, applications and placement administration.';
        } else if (isPlacementOfficer) {
            roleDescription = 'Manage students, placement drives, applications and placement activities.';
        } else if (isInterviewer) {
            roleDescription = 'Manage assigned interviews, candidate evaluations and interview outcomes.';
        }

        var staffFields = [userName, username, userEmail, userMobile, userTitle, userDepartment];
        var done = 0;

        for (var s = 0; s < staffFields.length; s++) {
            if (staffFields[s] && String(staffFields[s]).trim() !== '') {
                done++;
            }
        }

        var staffCompletion = Math.round((done / staffFields.length) * 100);

        data.profile = {
            role: role,
            roleLabel: role,
            isStudent: false,
            isOfficer: isPlacementOfficer,
            isAdmin: isPlacementAdmin,
            isInterviewer: isInterviewer,

            sys_id: userId,
            fullName: userName,
            email: userEmail,
            mobile: userMobile,
            title: userTitle,
            department: userDepartment,
            roleDescription: roleDescription,

            username: username,
            status: userActive ? 'Active' : 'Inactive',
            createdOn: userCreatedOn,
            completion: staffCompletion,
            profileCompletion: staffCompletion,

            statistics: data.statistics
        };
    }


    /* =========================================================
       UNKNOWN USER
       ========================================================= */

    function loadUnknownProfile() {

        data.profile = {
            fullName: userName,
            email: userEmail,
            mobile: userMobile,
            username: username,
            role: 'User',
            roleLabel: 'User',
            status: userActive ? 'Active' : 'Inactive',
            createdOn: userCreatedOn,
            completion: 0,
            profileCompletion: 0,
            isStudent: false,
            isOfficer: false,
            isAdmin: false,
            isInterviewer: false,
            statistics: data.statistics
        };
    }

})();
